fisiere.legislatie_portal.py:
"""
legislatie_portal.py — Portalul legislativ al Ministerului Justiției (legislatie.just.ro).

Pagina unui act (https://legislatie.just.ro/Public/DetaliiDocument/{id}) are textul în HTML, cu structura păstrată:
articolul (S_ART) cuprinde titlul (S_ART_TTL, „Articolul 416”), denumirea (S_ART_DEN) și corpul (S_ART_BDY), iar în corp
stau alineatele (S_ALN) și literele (S_LIT). Modulul:

  • descarcă pagina, cu reîncercări (portalul dă uneori 502 câteva secunde);
  • verifică pagina înainte să intre în dicționarul de legi: are articole, e pagina actului la zi (nu o consolidare
    fixată din istoric) și titlul are numărul și anul legii;
  • împarte actul pe articole, după regulile verificate pe Codul de procedură civilă și pe OUG 80/2013:
      - un articol aflat în alt articol e citat dintr-o altă lege („Articolul 36 din OG nr. 2/2001 se modifică…”):
        nu e articol al actului;
      - notele (S_NTA, de ex. deciziile RIL/HP) stau după articol, nu în el: se lipesc de articolul dinainte;
      - „Articolul 1.000” e art. 1000 (punctul de la mii), „Articolul 154^1” rămâne 154^1;
  • păstrează actul pe disc (cache/legislatie/<id>.json) și îl descarcă din nou după REIMPROSPATARE_ZILE sau la cerere;
  • alege din istoricul consolidărilor forma în vigoare la o dată dată (pentru faptele mai vechi).

Pagina la zi și consolidarea fixată: în „istoric consolidări”, forma afișată e cea roșie. Pe pagina actului (id-ul din
căutare sau din pagina principală) ea nu are atributul id='fa_selectata' și se schimbă singură la fiecare consolidare
nouă; pe pagina unei consolidări deschise din istoric îl are și rămâne înghețată la data ei, chiar dacă e cea mai nouă.
"""

from __future__ import annotations

import datetime
import json
import os
import re
import time
import unicodedata
from dataclasses import dataclass, field, asdict

from logger import get_logger
from safe_io import atomic_write_json

log = get_logger(__name__)

URL_PORTAL = "https://legislatie.just.ro"
URL_PAGINA_PRINCIPALA = URL_PORTAL + "/Public/"
URL_DOCUMENT = URL_PORTAL + "/Public/DetaliiDocument/{id}"

# Portalul refuză (403) cererile fără un User-Agent de browser
_ANTETE = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"}
INCERCARI = 4
PAUZA_INTRE_INCERCARI = 3          # secunde
TIMP_MAXIM_CERERE = 120            # secunde; pagina Codului civil are ~6 MB

REIMPROSPATARE_ZILE = 7
VERSIUNE_CACHE = 2                 # 2: articolele au și fragmentele (alineatele și literele, separat)

# Cele patru coduri, cu legăturile de pe pagina principală a portalului (verificate la 14.11.2026). Se folosesc doar
# când pagina principală nu se poate citi și nici nu e citită de altă dată.
COD_CIVIL = "cod_civil"
COD_PROCEDURA_CIVILA = "cod_procedura_civila"
COD_PENAL = "cod_penal"
COD_PROCEDURA_PENALA = "cod_procedura_penala"
ID_CODURI_IMPLICITE = {
    COD_CIVIL: 109884,
    COD_PROCEDURA_CIVILA: 140271,
    COD_PENAL: 109855,
    COD_PROCEDURA_PENALA: 120611,
}
# Textul legăturii de pe pagina principală (normalizat) -> codul
_LEGATURI_CODURI = {
    "noul cod civil": COD_CIVIL,
    "noul cod de procedura civila": COD_PROCEDURA_CIVILA,
    "noul cod penal": COD_PENAL,
    "noul cod de procedura penala": COD_PROCEDURA_PENALA,
}


class EroarePortal(Exception):
    """Portalul nu a răspuns (după toate reîncercările) sau pagina nu e a unui act."""


# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
# Structurile
# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────

@dataclass
class Consolidare:
    """O formă din „istoric consolidări”."""
    data: str                  # ISO, „2025-12-01”
    id: int | None             # pagina formei; la forma afișată pe pagina actului, id-ul consolidării curente
    afisata: bool = False      # forma afișată pe pagina citită (roșie în istoric)


@dataclass
class Articol:
    numar: str                 # „416”, „154^1”, „1000”
    titlu: str                 # „Articolul 416”
    denumire: str = ""
    alineate: list[str] = field(default_factory=list)
    text: str = ""             # tot corpul articolului: alineatele, literele și punctele, în ordine
    note: list[str] = field(default_factory=list)
    # Fiecare alineat și fiecare literă, fără notele de modificare („(la 18-07-2020, … a fost modificat …)”), după
    # cheia „alineat|literă”: „1|” = alin. (1) întreg, „1|b” = alin. (1) lit. b), „|a” = lit. a) a unui articol fără
    # alineate, „|” = corpul articolului fără alineate. Din ele se citesc cifrele (de ex. calculatorul taxei de timbru).
    fragmente: dict[str, str] = field(default_factory=dict)

    def fragment(self, alineat: str = "", litera: str = "") -> str | None:
        """Textul alineatului / literei („2^1”, „b”), fără notele de modificare; None dacă nu există."""
        return self.fragmente.get(f"{_eticheta_curata(str(alineat))}|{_eticheta_curata(litera)}")

    def ca_text(self) -> str:
        """Articolul întreg, gata de dat analizatorului: titlul, alineatele (sau corpul) și notele."""
        rand_titlu = self.titlu + (f" – {self.denumire}" if self.denumire else "")
        corp = "\n".join(self.alineate) if self.alineate else self.text
        parti = [rand_titlu, corp]
        parti += [f"Notă: {n}" for n in self.note]
        return "\n".join(p for p in parti if p)


@dataclass
class ActLegislativ:
    id: int
    titlu: str = ""
    id_consolidare: int | None = None          # câmpul ascuns id_act: consolidarea afișată
    data_consolidarii: str = ""                # ISO; gol la un act nemodificat (fără istoric)
    consolidare_fixa: bool = False             # pagina unei consolidări deschise din istoric (nu se mai schimbă)
    id_forma_de_baza: int | None = None        # textul publicat inițial („Forma de baza”)
    istoric: list[Consolidare] = field(default_factory=list)
    articole: dict[str, Articol] = field(default_factory=dict)
    articole_duble: list[str] = field(default_factory=list)
    descarcat_la: str = ""

    @property
    def url(self) -> str:
        return URL_DOCUMENT.format(id=self.id)

    def articol(self, numar) -> Articol | None:
        """Articolul după număr, scris oricum: 416, „art. 416”, „1.000”, „154^1”, „154 ind. 1”, „154¹”."""
        return self.articole.get(normalizeaza_numar_articol(str(numar)))

    def to_dict(self) -> dict:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict) -> "ActLegislativ":
        d = dict(d)
        d["istoric"] = [Consolidare(**c) for c in d.get("istoric", [])]
        d["articole"] = {k: Articol(**a) for k, a in d.get("articole", {}).items()}
        return cls(**d)


@dataclass
class RezultatVerificare:
    """Ce a găsit verificarea unui id pentru dicționar."""
    id: int
    act: ActLegislativ | None = None
    probleme: list[str] = field(default_factory=list)       # oricare oprește intrarea în dicționar
    avertismente: list[str] = field(default_factory=list)
    id_propus: int | None = None                             # id-ul bun găsit în locul celui dat
    act_propus: ActLegislativ | None = None

    @property
    def ok(self) -> bool:
        return self.act is not None and not self.probleme


# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
# Texte și numere
# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────

def fara_diacritice(text: str) -> str:
    """„Procedură civilă” -> „Procedura civila” (și ş/ţ cu sedilă)."""
    return "".join(c for c in unicodedata.normalize("NFKD", text) if not unicodedata.combining(c))


def _text(el) -> str:
    return re.sub(r"\s+", " ", el.get_text(" ")).strip() if el is not None else ""


_SUPERSCRIPT = str.maketrans("⁰¹²³⁴⁵⁶⁷⁸⁹", "0123456789")


def normalizeaza_numar_articol(text: str) -> str:
    """„Articolul 1.000” -> „1000”; „art. 154^1”, „154 ind. 1”, „154¹” -> „154^1”; „Articolul I” -> „I” (legile care
    modifică alte legi au articole cu cifre romane). Ce nu e un număr de articol rămâne cum e."""
    # Indicele superior întâi: descompunerea diacriticelor (NFKD) ar face din „154¹” numărul „1541”
    t = re.sub(r"\s*([⁰¹²³⁴⁵⁶⁷⁸⁹]+)", lambda m: "^" + m.group(1).translate(_SUPERSCRIPT), text)
    t = fara_diacritice(t).strip().lower()
    t = re.sub(r"^(articolul|articol|art)\.?\s*", "", t)
    # „art. 5 alin. (2) lit. a)” -> art. 5: se dă oricum articolul întreg
    t = re.sub(r"[\s,]+(alin|alineat|alineatul|lit|litera|pct|punctul|teza|par)\b.*$", "", t)
    if t == "unic":                   # „ARTICOL UNIC”, „art. unic”
        return "UNIC"
    m = re.match(r"^(\d{1,3}(?:\.\d{3})+|\d+|[ivxlcdm]+)\s*(?:\^\s*(\d+)|ind(?:ice|ex)?\.?\s*(\d+))?$", t)
    if not m:
        return text.strip()
    numar = m.group(1).replace(".", "")
    numar = numar.upper() if not numar.isdigit() else numar
    indice = m.group(2) or m.group(3)
    return f"{numar}^{indice}" if indice else numar


def _data_iso(zz_ll_aaaa: str) -> str:
    return datetime.datetime.strptime(zz_ll_aaaa, "%d.%m.%Y").date().isoformat()


def id_din_text(text: str) -> int | None:
    """Id-ul din ce lipește utilizatorul: „149314” sau o legătură …/DetaliiDocument/149314 (și …DetaliiDocumentAfis/…)."""
    t = (text or "").strip()
    m = re.search(r"DetaliiDocument(?:Afis)?/(\d+)", t, re.I) or re.fullmatch(r"(\d+)", t)
    return int(m.group(1)) if m else None


def numar_si_an(eticheta: str) -> tuple[str, str] | None:
    """„OUG 80/2013”, „Legea nr. 10/1995” -> („80”, „2013”); fără număr/an (de ex. „Codul civil”) -> None."""
    m = re.search(r"(\d{1,3}(?:\.\d{3})+|\d+)\s*/\s*((?:19|20)\d{2})\b", eticheta or "")
    return (m.group(1).replace(".", ""), m.group(2)) if m else None


# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
# Citirea paginii
# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────

def _supa(html: str):
    from bs4 import BeautifulSoup
    try:
        return BeautifulSoup(html, "lxml")
    except Exception:                       # lxml lipsă: parserul din biblioteca standard (mai lent, același rezultat)
        log.warning("lxml indisponibil; pagina portalului se citește cu html.parser", exc_info=True)
        return BeautifulSoup(html, "html.parser")


def _istoricul(supa, id_consolidare: int | None) -> tuple[list[Consolidare], bool]:
    """Formele din „istoric consolidări”, de la cea mai nouă; și dacă pagina e o consolidare fixată din istoric."""
    bloc = supa.find(id="istoric_fa")
    if bloc is None:
        return [], False
    forme, fixa = [], False
    for a in bloc.find_all("a"):
        m = re.search(r"\d{2}\.\d{2}\.\d{4}", a.get_text())
        if not m:
            continue
        afisata = "color:red" in (a.get("style") or "").replace(" ", "")
        if afisata and a.get("id") == "fa_selectata":
            fixa = True
        legatura = re.search(r"DetaliiDocument/(\d+)", a.get("href") or "")
        id_forma = int(legatura.group(1)) if legatura else (id_consolidare if afisata else None)
        forme.append(Consolidare(_data_iso(m.group(0)), id_forma, afisata))
    forme.sort(key=lambda c: c.data, reverse=True)
    return forme, fixa


def _numar_intreg(supa, selector, atribut="value") -> int | None:
    el = supa.select_one(selector)
    v = (el.get(atribut) or "") if el is not None else ""
    return int(v) if v.isdigit() else None


def _forma_de_baza(supa) -> int | None:
    el = supa.find(id="Formadebaza")
    m = re.search(r"incarcaFormaDeBaza\((\d+)\)", (el.get("onchange") or "") if el is not None else "")
    return int(m.group(1)) if m else None


def _este_articol_al_actului(el) -> bool:
    """Un articol aflat în alt articol e citat dintr-o altă lege (textul modificat de actul citit)."""
    return el.find_parent(class_="S_ART") is None


def _textul_notei(nota) -> str:
    lung = nota.find(id=re.compile(r"_lung$"))
    return _text(lung if lung is not None else nota)


# Marcajele paginii care nu sunt text de lege: „...” de restrângere a literelor / notelor, „+” de lângă titluri
_MARCAJE = frozenset({"S_LIT_SHORT", "S_NTA_SHORT", "TAG_COLLAPSED"})
# În fragmente (de unde se citesc cifre) lipsesc și notele (S_NTA) și notele de modificare (vezi _NOTA_DE_MODIFICARE)
_FARA_IN_FRAGMENTE = _MARCAJE | {"S_NTA", _NOTA_DE_MODIFICARE := "nota_de_modificare"}
# Nota de modificare e un paragraf S_PAR („(la 18-07-2020, Alineatul (1) … a fost modificat de …)”); tot S_PAR sunt
# însă și paragrafele obișnuite ale articolului („Se taxează cu 20 lei următoarele cereri …”)
_INCEPUT_NOTA_DE_MODIFICARE = re.compile(r"^\s*\(la \d{2}-\d{2}-\d{4},")


def _clasele(tag) -> set:
    clase = set(tag.get("class") or [])
    if "S_PAR" in clase and _INCEPUT_NOTA_DE_MODIFICARE.match(tag.get_text(" ")):
        clase.add(_NOTA_DE_MODIFICARE)
    return clase


def _text_fara(el, clase_excluse) -> str:
    """Textul elementului, fără subelementele care au una dintre clasele date."""
    from bs4.element import NavigableString, Comment
    parti = []

    def umbla(nod):
        for copil in nod.children:
            if isinstance(copil, NavigableString):
                if not isinstance(copil, Comment):
                    parti.append(str(copil))
            elif not (_clasele(copil) & clase_excluse):
                umbla(copil)
    if el is not None:
        umbla(el)
    return re.sub(r"\s+", " ", " ".join(parti)).strip()


def _eticheta_curata(eticheta: str) -> str:
    """„(2^1)” -> „2^1”, „a)” -> „a”, „ g^1) ” -> „g^1”."""
    return re.sub(r"[()\s]", "", eticheta or "").lower()


def _fragmentele(corp) -> dict[str, str]:
    """Alineatele și literele articolului, separat, după cheia „alineat|literă” (vezi Articol.fragmente)."""
    fragmente = {"|": _text_fara(corp, _FARA_IN_FRAGMENTE)}

    def literele(parinte, alineat):
        for lit in parinte.select(".S_LIT"):
            if lit.find_parent(class_="S_LIT") is not None:
                continue
            if alineat == "" and lit.find_parent(class_="S_ALN") is not None:
                continue
            eticheta = _eticheta_curata(_text(lit.select_one(".S_LIT_TTL")))
            corp_lit = lit.select_one(".S_LIT_BDY") or lit
            if eticheta:
                fragmente.setdefault(f"{alineat}|{eticheta}", _text_fara(corp_lit, _FARA_IN_FRAGMENTE))

    for aln in corp.select(".S_ALN"):
        if aln.find_parent(class_="S_ALN") is not None:
            continue
        eticheta = _eticheta_curata(_text(aln.select_one(".S_ALN_TTL")))
        corp_aln = aln.select_one(".S_ALN_BDY") or aln
        if eticheta:
            fragmente.setdefault(f"{eticheta}|", _text_fara(corp_aln, _FARA_IN_FRAGMENTE))
            literele(corp_aln, eticheta)
    literele(corp, "")
    return fragmente


def _citeste_articolul(el) -> tuple[Articol, list[str]]:
    """Articolul din elementul S_ART; notele găsite chiar în el (rar) sunt scoase din text și întoarse separat."""
    titlu = _text(el.select_one(".S_ART_TTL"))
    corp = el.select_one(".S_ART_BDY")
    fara = _MARCAJE | {"S_NTA"}
    note_interioare, alineate, fragmente = [], [], {}
    if corp is not None:
        note_interioare = [_textul_notei(n) for n in corp.select(".S_NTA") if n.find_parent(class_="S_NTA") is None]
        alineate = [_text_fara(a, fara) for a in corp.select(".S_ALN") if a.find_parent(class_="S_ALN") is None]
        fragmente = _fragmentele(corp)
    articol = Articol(
        numar=normalizeaza_numar_articol(titlu), titlu=titlu,
        denumire=_text(el.select_one(".S_ART_DEN")),
        alineate=[a for a in alineate if a],
        text=_text_fara(corp, fara),
        fragmente=fragmente,
    )
    return articol, note_interioare


def _articolele(supa) -> tuple[dict[str, Articol], list[str]]:
    """Articolele actului, în ordine, fiecare cu notele de după el. Un număr repetat (de ex. într-o anexă care își
    numerotează din nou articolele) se păstrează cu primul articol; numerele repetate se întorc separat."""
    articole, duble, curent = {}, [], None
    for el in supa.find_all(class_=["S_ART", "S_NTA"]):
        clase = el.get("class") or []
        if "S_ART" in clase:
            if not _este_articol_al_actului(el):
                continue
            articol, note = _citeste_articolul(el)
            if articol.numar in articole:
                duble.append(articol.numar)
                curent = None          # notele de după articolul repetat nu se lipesc de primul
                continue
            articol.note.extend(note)
            articole[articol.numar] = curent = articol
        elif curent is not None and el.find_parent(class_=["S_NTA", "S_ART"]) is None:
            curent.note.append(_textul_notei(el))
    return articole, duble


def analizeaza_pagina(html: str, id_document: int) -> ActLegislativ:
    """Pagina DetaliiDocument/{id} citită: titlul, consolidarea afișată, istoricul și articolele."""
    supa = _supa(html)
    titlu = " ".join(t for t in (_text(supa.select_one(".S_DEN")), _text(supa.select_one(".S_HDR"))) if t)
    id_consolidare = _numar_intreg(supa, "input#id_act")
    istoric, fixa = _istoricul(supa, id_consolidare)
    afisata = next((c for c in istoric if c.afisata), None)
    articole, duble = _articolele(supa)
    return ActLegislativ(
        id=id_document, titlu=titlu, id_consolidare=id_consolidare,
        data_consolidarii=afisata.data if afisata else "", consolidare_fixa=fixa,
        id_forma_de_baza=_forma_de_baza(supa), istoric=istoric, articole=articole, articole_duble=duble,
        descarcat_la=datetime.datetime.now().isoformat(timespec="seconds"),
    )


def coduri_de_pe_pagina_principala(html: str) -> dict[str, int]:
    """Id-urile celor patru coduri, din legăturile „Noile Coduri” ale paginii principale."""
    supa = _supa(html)
    coduri = {}
    for a in supa.find_all("a", href=True):
        m = re.search(r"/Public/DetaliiDocument/(\d+)$", a["href"])
        cod = _LEGATURI_CODURI.get(fara_diacritice(_text(a)).lower()) if m else None
        if cod and cod not in coduri:
            coduri[cod] = int(m.group(1))
    return coduri


# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
# Verificarea pentru dicționar
# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────

def _titlul_are_numarul(titlu: str, numar: str, an: str) -> bool:
    t = re.sub(r"(\d)\.(\d{3})", r"\1\2", fara_diacritice(titlu).lower())     # „nr. 1.481” -> „nr. 1481”
    return bool(re.search(rf"\b{numar}\s*/\s*{an}\b", t)
                or (re.search(rf"\bnr\.?\s*{numar}\b", t) and re.search(rf"\b{an}\b", t)))


def verifica_actul(act: ActLegislativ, eticheta: str = "") -> tuple[list[str], list[str]]:
    """Problemele care opresc intrarea actului în dicționar și avertismentele care doar se arată."""
    probleme, avertismente = [], []
    if not act.articole:
        probleme.append("Pagina nu are articole: e doar o trimitere (de exemplu la forma republicată) sau un act fără "
                        "text. Deschide pagina în browser și ia id-ul paginii care are textul actului.")
    if act.consolidare_fixa:
        data = _data_ro(act.data_consolidarii)
        probleme.append(f"Pagina e consolidarea din {data}, deschisă din istoric: rămâne la forma de atunci și nu se mai "
                        "actualizează. Trebuie id-ul paginii actului (cel din căutare), care arată mereu ultima "
                        "consolidare.")
    nr_an = numar_si_an(eticheta)
    if nr_an and act.titlu and not _titlul_are_numarul(act.titlu, *nr_an):
        probleme.append(f"Titlul de pe portal nu are numărul {nr_an[0]}/{nr_an[1]}: „{act.titlu}”.")
    if act.articole_duble:
        avertismente.append("Unele articole au același număr (probabil într-o anexă care își numerotează din nou "
                            f"articolele): {', '.join(sorted(set(act.articole_duble))[:10])}. Se folosește primul.")
    return probleme, avertismente


def _data_ro(iso: str) -> str:
    try:
        return datetime.date.fromisoformat(iso).strftime("%d.%m.%Y")
    except ValueError:
        return iso or "?"


def verifica_pentru_dictionar(id_document: int, eticheta: str = "") -> RezultatVerificare:
    """Descarcă pagina id-ului și o verifică. La o consolidare fixată din istoric încearcă și forma de bază a actului:
    dacă aceea e pagina actului la zi, cu articole și cu numărul potrivit, o propune în loc."""
    rezultat = RezultatVerificare(id=id_document)
    try:
        rezultat.act = descarca_act(id_document)
    except EroarePortal as e:
        rezultat.probleme.append(str(e))
        return rezultat
    rezultat.probleme, rezultat.avertismente = verifica_actul(rezultat.act, eticheta)
    baza = rezultat.act.id_forma_de_baza
    if rezultat.act.consolidare_fixa and baza and baza != id_document:
        try:
            act_baza = descarca_act(baza)
        except EroarePortal:
            log.warning("Forma de bază %s a actului %s nu s-a putut citi", baza, id_document, exc_info=True)
            return rezultat
        if not verifica_actul(act_baza, eticheta)[0]:
            rezultat.id_propus, rezultat.act_propus = baza, act_baza
    return rezultat


# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
# Descărcarea și păstrarea pe disc
# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────

def _descarca_html(url: str) -> str:
    """Pagina de la `url`; reîncearcă la erori de rețea și la 5xx (portalul dă uneori 502 câteva secunde)."""
    import requests
    ultima_eroare = None
    for incercare in range(1, INCERCARI + 1):
        try:
            r = requests.get(url, headers=_ANTETE, timeout=TIMP_MAXIM_CERERE)
            if r.status_code < 500:
                r.raise_for_status()
                r.encoding = r.encoding or "utf-8"
                return r.text
            ultima_eroare = f"HTTP {r.status_code}"
        except requests.HTTPError as e:
            raise EroarePortal(f"Portalul a refuzat cererea ({e.response.status_code}): {url}") from e
        except requests.RequestException as e:
            ultima_eroare = str(e)
        log.info("Portalul legislativ: încercarea %d/%d pentru %s a eșuat (%s)", incercare, INCERCARI, url, ultima_eroare)
        if incercare < INCERCARI:
            time.sleep(PAUZA_INTRE_INCERCARI)
    raise EroarePortal(f"Portalul legislativ nu răspunde ({ultima_eroare}). Încearcă din nou peste câteva minute.")


def _folder_cache() -> str:
    from config_manager import _APP_DIR
    return os.path.join(_APP_DIR, "cache", "legislatie")


def _cale_act(id_document: int) -> str:
    return os.path.join(_folder_cache(), f"{int(id_document)}.json")


def _citeste_din_cache(id_document: int) -> ActLegislativ | None:
    cale = _cale_act(id_document)
    if not os.path.isfile(cale):
        return None
    try:
        with open(cale, encoding="utf-8") as f:
            date = json.load(f)
        if date.get("versiune") != VERSIUNE_CACHE:
            return None
        return ActLegislativ.from_dict(date["act"])
    except Exception:
        log.warning("Actul %s din cache-ul portalului nu se poate citi; se descarcă din nou", id_document, exc_info=True)
        return None


def _scrie_in_cache(act: ActLegislativ):
    try:
        atomic_write_json(_cale_act(act.id), {"versiune": VERSIUNE_CACHE, "act": act.to_dict()})
    except OSError:
        log.warning("Actul %s nu s-a putut păstra în cache", act.id, exc_info=True)


def descarca_act(id_document: int) -> ActLegislativ:
    """Pagina actului, descărcată acum și citită; o pagină cu articole se păstrează și pe disc."""
    html = _descarca_html(URL_DOCUMENT.format(id=int(id_document)))
    act = analizeaza_pagina(html, int(id_document))
    if not act.titlu and not act.articole:
        raise EroarePortal(f"Pagina {act.url} nu e pagina unui act (lipsesc titlul și articolele).")
    if act.articole:
        _scrie_in_cache(act)
    return act


def _e_proaspat(act: ActLegislativ, max_zile: int) -> bool:
    if act.consolidare_fixa:           # o consolidare din istoric nu se mai schimbă
        return True
    try:
        descarcat = datetime.datetime.fromisoformat(act.descarcat_la)
    except ValueError:
        return False
    return datetime.datetime.now() - descarcat < datetime.timedelta(days=max_zile)


def obtine_act(id_document: int, *, reimprospateaza: bool = False,
               max_zile: int = REIMPROSPATARE_ZILE) -> ActLegislativ:
    """Actul de pe disc, dacă e descărcat de mai puțin de `max_zile`; altfel (sau la cerere) îl descarcă din nou.
    Când portalul nu răspunde, se folosește copia de pe disc, oricât de veche; fără copie, EroarePortal."""
    din_cache = _citeste_din_cache(id_document)
    if din_cache is not None and not reimprospateaza and _e_proaspat(din_cache, max_zile):
        return din_cache
    try:
        return descarca_act(id_document)
    except EroarePortal:
        if din_cache is None:
            raise
        log.warning("Portalul nu răspunde; actul %s se folosește din copia descărcată la %s",
                    id_document, din_cache.descarcat_la, exc_info=True)
        return din_cache


def _cale_coduri() -> str:
    return os.path.join(_folder_cache(), "coduri.json")


def id_coduri(*, reimprospateaza: bool = False, doar_local: bool = False) -> dict[str, int]:
    """Id-urile celor patru coduri: de pe pagina principală (citită cel mult o dată pe săptămână), altfel cele
    păstrate de la ultima citire, altfel cele verificate la scrierea modulului. Cu `doar_local` nu se descarcă nimic
    (pentru firul ferestrelor)."""
    pastrate = {}
    try:
        with open(_cale_coduri(), encoding="utf-8") as f:
            date = json.load(f)
        pastrate = {k: int(v) for k, v in date.get("coduri", {}).items()}
        citite = datetime.datetime.fromisoformat(date.get("citite_la", ""))
        if not reimprospateaza and len(pastrate) == 4 and \
                datetime.datetime.now() - citite < datetime.timedelta(days=REIMPROSPATARE_ZILE):
            return pastrate
    except (OSError, ValueError, TypeError, AttributeError):
        pass
    if doar_local:
        return {**ID_CODURI_IMPLICITE, **pastrate}
    try:
        coduri = coduri_de_pe_pagina_principala(_descarca_html(URL_PAGINA_PRINCIPALA))
    except EroarePortal:
        log.warning("Pagina principală a portalului nu răspunde; id-urile codurilor rămân cele știute", exc_info=True)
        coduri = {}
    if len(coduri) == 4:
        try:
            atomic_write_json(_cale_coduri(), {"coduri": coduri,
                                               "citite_la": datetime.datetime.now().isoformat(timespec="seconds")})
        except OSError:
            log.warning("Id-urile codurilor nu s-au putut păstra", exc_info=True)
        return coduri
    if coduri:
        log.warning("Pe pagina principală a portalului s-au găsit doar codurile %s", sorted(coduri))
    return {**ID_CODURI_IMPLICITE, **pastrate, **coduri}


# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
# Forma în vigoare la o dată
# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────

def alege_consolidarea(act: ActLegislativ, la_data: datetime.date | str) -> Consolidare | None:
    """Ultima consolidare cu data cel mult `la_data`. None când data e dinaintea primei consolidări din istoric (forma
    de atunci e textul inițial sau o formă pe care istoricul nu o are) sau când actul nu are istoric."""
    data = la_data.isoformat() if isinstance(la_data, datetime.date) else str(la_data)
    return next((c for c in act.istoric if c.data <= data), None)


def obtine_forma_la_data(id_document: int, la_data: datetime.date | str) -> ActLegislativ | None:
    """Actul în forma consolidată în vigoare la `la_data`. Actul fără istoric (nemodificat) e întors așa cum e; None
    când data e dinaintea primei consolidări din istoric."""
    act = obtine_act(id_document)
    if not act.istoric:
        return act
    forma = alege_consolidarea(act, la_data)
    if forma is None:
        return None
    if forma.afisata or forma.id in (None, act.id):
        return act
    return obtine_act(forma.id)

fisiere.taxa_timbru.py:
"""
taxa_timbru.py — Calculatorul taxei judiciare de timbru (OUG nr. 80/2013).

Regulile de calcul sunt aici, în cod: „treapta în care cade valoarea dă suma fixă plus procentul din ce depășește
pragul”, „apelul se taxează cu un procent din taxa de la fond, dar nu mai puțin de un minim” etc. Cifrele (pragurile,
sumele, procentele, minimele, plafoanele) NU sunt în cod: se citesc la fiecare calcul din textul ordonanței în forma
consolidată de pe portalul legislativ (legislatie_portal), din punctul exact care le stabilește — de pildă art. 3
alin. (1) lit. c): „între 5.001 lei și 25.000 lei - 355 lei + 5% pentru ce depășește 5.000 lei”. Când ordonanța se
modifică, portalul publică o consolidare nouă, iar calculatorul folosește singur noile cifre.

Nu există cifre de rezervă. Dacă un punct și-a schimbat forma (sau a dispărut) și cifrele lui nu se mai pot citi
sigur, cazul respectiv refuză calculul (CifreIlizibile) și arată textul nou, ca judecătorul să calculeze după el; nu se
calculează niciodată cu cifre vechi.

Taxa se calculează după forma în vigoare la data cererii (implicit azi): pentru o dată mai veche se folosește
consolidarea de atunci, din istoricul consolidărilor de pe portal.
"""

from __future__ import annotations

import datetime
import re
from dataclasses import dataclass, field
from decimal import Decimal, ROUND_HALF_UP
from typing import Callable

import legislatie_portal as portal
from logger import get_logger

log = get_logger(__name__)

NUME_ORDONANTA = "OUG 80/2013"
ID_OUG_80_2013 = 149314           # pagina actului de pe portal (verificată la 15.11.2026); dicționarul are prioritate


class CifreIlizibile(Exception):
    """Cifrele unui punct al ordonanței nu se pot citi sigur din forma consolidată (punctul s-a schimbat sau lipsește)."""

    def __init__(self, temei: "Temei", text: str | None, motiv: str):
        self.temei, self.text, self.motiv = temei, text, motiv
        super().__init__(f"{temei}: {motiv}")


class TexteIndisponibile(Exception):
    """Textul ordonanței nu se poate obține (portal fără răspuns și nicio copie pe disc, dată fără formă în istoric)."""


# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
# Sume și procente din text
# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────

_NUMAR = r"(\d{1,3}(?:\.\d{3})+|\d+)(?:,(\d+))?"
_LEI = _NUMAR + r"\s*(?:lei|leu)\b"
_PROCENT = _NUMAR + r"\s*%"


def _decimal(intreg: str, zecimale: str | None) -> Decimal:
    return Decimal(intreg.replace(".", "") + ("." + zecimale if zecimale else ""))


def sume_in_lei(text: str) -> list[Decimal]:
    """„40 lei + 7% pentru ce depășește 500 lei” -> [40, 500]; „0,20 lei/pagină” -> [0.20]; „1.355 lei” -> [1355]."""
    return [_decimal(a, b) for a, b in re.findall(_LEI, text or "")]


def procente(text: str) -> list[Decimal]:
    return [_decimal(a, b) for a, b in re.findall(_PROCENT, text or "")]


def _simplu(text: str) -> str:
    """Pentru potrivirea formulărilor: fără diacritice, litere mici, spații simple."""
    return re.sub(r"\s+", " ", portal.fara_diacritice(text or "").lower()).strip()


def _rotunjeste(suma: Decimal) -> Decimal:
    return suma.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def lei(suma: Decimal) -> str:
    """1355 -> „1.355 lei”; 40.5 -> „40,50 lei”; 0.2 -> „0,20 lei”."""
    suma = _rotunjeste(Decimal(suma))
    intreg, _, zecimale = f"{suma:.2f}".partition(".")
    semn = "-" if intreg.startswith("-") else ""
    intreg = intreg.lstrip("-")
    grupe = f"{int(intreg):,}".replace(",", ".")
    unitate = "leu" if suma == 1 else "lei"
    return f"{semn}{grupe}{',' + zecimale if zecimale != '00' else ''} {unitate}"


def citeste_suma(text: str) -> Decimal:
    """Suma scrisă de judecător: „12.000”, „12 000”, „12000”, „12.000,50”, „705,5”, „705.5” (punct zecimal doar când nu
    poate fi separator de mii). ValueError dacă nu e o sumă."""
    t = re.sub(r"\s|lei|leu", "", (text or "").strip().lower())
    if "," in t:
        t = t.replace(".", "").replace(",", ".")
    elif re.fullmatch(r"\d{1,3}(?:\.\d{3})+", t):
        t = t.replace(".", "")
    if not re.fullmatch(r"\d+(?:\.\d+)?", t):
        raise ValueError(f"„{text}” nu e o sumă în lei.")
    return Decimal(t)


def _procent(p: Decimal) -> str:
    return f"{p.normalize():f}".replace(".", ",") + "%"


# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
# Ordonanța citită
# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────

OUG, CPC = "oug", "cpc"                     # actele din care se citesc cifrele
NUME_ACTE = {OUG: "OUG nr. 80/2013", CPC: "Codul de procedură civilă"}


@dataclass(frozen=True)
class Temei:
    art: str
    alin: str = ""
    lit: str = ""
    act: str = OUG

    def __str__(self) -> str:
        art = self.art
        if art.isdigit() and len(art) > 3:                  # „art. 1.057”, ca în cod
            art = f"{art[:-3]}.{art[-3:]}"
        return (f"art. {art}" + (f" alin. ({self.alin})" if self.alin else "")
                + (f" lit. {self.lit})" if self.lit else "") + (" C.pr.civ." if self.act == CPC else ""))


@dataclass
class Treapta:
    """O literă a art. 3 alin. (1): pentru valorile până la `pana_la` (None = fără limită), taxa e `fix` + `procent`
    din ce depășește `peste`, dar nu mai puțin de `minim`."""
    litera: str
    de_la: Decimal
    pana_la: Decimal | None
    fix: Decimal
    procent: Decimal
    peste: Decimal
    minim: Decimal = Decimal(0)


def _forma(act: portal.ActLegislativ | None) -> str:
    if act is None:
        return "forma necitită"
    return (f"forma consolidată la {portal._data_ro(act.data_consolidarii)}" if act.data_consolidarii
            else "forma publicată")


class TexteLegale:
    """Textele din care se citesc cifrele, în forma în vigoare la data cererii: OUG 80/2013 (`act`, taxele) și Codul
    de procedură civilă (`cpc`, cauțiunile; poate lipsi, iar atunci doar cauțiunile refuză calculul)."""

    def __init__(self, act: portal.ActLegislativ, cpc: portal.ActLegislativ | None = None, *,
                 problema_cpc: str = ""):
        self.act = act
        self.cpc = cpc
        self.problema_cpc = problema_cpc            # de ce lipsește Codul de procedură civilă
        self._trepte: list[Treapta] | None = None
        self._trepte_cautiune: list[Treapta] | None = None

    @property
    def data_consolidarii(self) -> str:
        return self.act.data_consolidarii

    @property
    def forma(self) -> str:
        """Forma ordonanței: „forma consolidată la 01.12.2025” (sau „forma publicată”, pentru un act fără istoric)."""
        return _forma(self.act)

    @property
    def forma_cpc(self) -> str:
        return _forma(self.cpc)

    def _actul(self, temei: Temei) -> portal.ActLegislativ:
        if temei.act == CPC:
            if self.cpc is None:
                raise CifreIlizibile(temei, None, "Codul de procedură civilă nu s-a putut citi"
                                                  + (f": {self.problema_cpc}" if self.problema_cpc else "."))
            return self.cpc
        return self.act

    def forma_pentru(self, temei: Temei) -> str:
        return self.forma_cpc if temei.act == CPC else self.forma

    def text(self, temei: Temei) -> str:
        """Textul punctului. Un articol fără alineate e alin. (1) al formelor de mai târziu (când i se adaugă alin. (2),
        textul lui devine alin. (1)), deci „alin. (1)” se caută și în corpul unui asemenea articol."""
        act = self._actul(temei)
        forma, al_cui = self.forma_pentru(temei), ("a ordonanței" if temei.act == OUG else "a Codului")
        articol = act.articol(temei.art)
        text = articol.fragment(temei.alin, temei.lit) if articol is not None else None
        fara_marcaje = articol is not None and set(articol.fragmente) <= {"|"}
        if not text and articol is not None and temei.alin == "1" and not re.match(r"\(\d", articol.text) \
                and not any(k.split("|")[0] for k in articol.fragmente):
            text = articol.fragment("", temei.lit)
        if not text and fara_marcaje and (temei.alin or temei.lit) and re.search(r"\(\d+\)|\b[a-z]\) ", articol.text):
            # Paginile vechi ale portalului (de ex. consolidarea din 2014) nu marchează alineatele și literele
            raise CifreIlizibile(temei, articol.text, f"în {forma} portalul nu marchează separat alineatele și "
                                                      "literele, deci cifrele nu se pot citi sigur pe puncte; "
                                                      "calculează după textul articolului.")
        if not text:
            raise CifreIlizibile(temei, None, f"punctul nu există în {forma} {al_cui}.")
        return text

    def verifica_reperul(self, temei: Temei, reper: str):
        """Punctul trebuie să vorbească tot despre același lucru (literele și alineatele se pot renumerota între forme):
        `reper` (fără diacritice, litere mici, expresie regulată) trebuie să apară în textul lui."""
        text = self.text(temei)
        if not re.search(reper, _simplu(text)):
            raise CifreIlizibile(temei, text, f"în {self.forma_pentru(temei)} punctul acesta privește altceva decât "
                                              "cazul ales.")

    def sume(self, temei: Temei, cate: int) -> list[Decimal]:
        """Sumele în lei din punct; trebuie să fie exact `cate`, altfel punctul s-a schimbat față de regula din cod."""
        text = self.text(temei)
        sume = sume_in_lei(text)
        if len(sume) != cate:
            raise CifreIlizibile(temei, text, f"aștept {cate} sum{'ă' if cate == 1 else 'e'} în lei, am găsit "
                                              f"{len(sume)}; textul s-a schimbat.")
        return sume

    def suma(self, temei: Temei) -> Decimal:
        return self.sume(temei, 1)[0]

    def procente(self, temei: Temei, cate: int) -> list[Decimal]:
        text = self.text(temei)
        gasite = procente(text)
        if len(gasite) != cate:
            raise CifreIlizibile(temei, text, f"aștept {cate} procent{'' if cate == 1 else 'e'}, am găsit "
                                              f"{len(gasite)}; textul s-a schimbat.")
        return gasite

    def potrivire(self, temei: Temei, model: str, ce: str) -> re.Match:
        """Formularea `model` (pe textul fără diacritice, cu litere mici) în punct; altfel CifreIlizibile."""
        text = self.text(temei)
        m = re.search(model, _simplu(text))
        if not m:
            raise CifreIlizibile(temei, text, f"nu mai găsesc {ce}; textul s-a schimbat.")
        return m

    def trepte(self) -> list[Treapta]:
        """Treptele art. 3 alin. (1), din literele lui, în ordine."""
        if self._trepte is None:
            self._trepte = self._citeste_treptele()
        return self._trepte

    def _citeste_treptele(self) -> list[Treapta]:
        temei = Temei("3", "1")
        articol = self.act.articol("3")
        if articol is None:
            raise CifreIlizibile(temei, None, "art. 3 nu mai există în forma consolidată a ordonanței.")
        litere = [(k.split("|")[1], t) for k, t in articol.fragmente.items() if k.startswith("1|") and k != "1|"]
        if not litere:
            self.text(Temei("3", "1", "a"))        # spune de ce lipsesc literele (punct dispărut sau pagină nemarcată)
        trepte = []
        for litera, text in litere:
            s = _simplu(text)
            if m := re.match(rf"pana la valoarea de {_LEI} - {_PROCENT},? dar nu mai putin de {_LEI}", s):
                trepte.append(Treapta(litera, Decimal(0), _decimal(*m.group(1, 2)), Decimal(0),
                                      _decimal(*m.group(3, 4)), Decimal(0), _decimal(*m.group(5, 6))))
            elif m := re.match(rf"intre {_LEI} si {_LEI} - {_LEI} ?\+ ?{_PROCENT} pentru ce depaseste {_LEI}", s):
                trepte.append(Treapta(litera, _decimal(*m.group(1, 2)), _decimal(*m.group(3, 4)),
                                      _decimal(*m.group(5, 6)), _decimal(*m.group(7, 8)), _decimal(*m.group(9, 10))))
            elif m := re.match(rf"peste {_LEI} - {_LEI} ?\+ ?{_PROCENT} pentru ce depaseste {_LEI}", s):
                trepte.append(Treapta(litera, _decimal(*m.group(1, 2)), None, _decimal(*m.group(3, 4)),
                                      _decimal(*m.group(5, 6)), _decimal(*m.group(7, 8))))
            else:
                raise CifreIlizibile(Temei("3", "1", litera), text, "forma treptei s-a schimbat.")
        self._verifica_treptele(trepte)
        return trepte

    def _verifica_treptele(self, trepte: list[Treapta]):
        temei = Temei("3", "1")
        text = self.act.articol("3").fragment("1")
        if len(trepte) < 2 or trepte[0].de_la != 0 or trepte[-1].pana_la is not None:
            raise CifreIlizibile(temei, text, "treptele nu mai acoperă toate valorile (de la 0 până peste ultima).")
        for anterioara, urmatoarea in zip(trepte, trepte[1:]):
            if anterioara.pana_la is None or urmatoarea.de_la not in (anterioara.pana_la, anterioara.pana_la + 1):
                raise CifreIlizibile(temei, text, f"treptele lit. {anterioara.litera}) și lit. {urmatoarea.litera}) "
                                                  "nu se mai continuă.")

    def trepte_cautiune(self) -> list[Treapta]:
        """Treptele cauțiunii de la art. 719 alin. (2) C.pr.civ.: „a) de 10%, dacă această valoare este până la 10.000
        lei; b) de 1.000 lei plus 5% pentru ceea ce depășește 10.000 lei; …”. Limita de sus a unei trepte e pragul
        următoarei (textul nu o spune altfel)."""
        if self._trepte_cautiune is None:
            self._trepte_cautiune = self._citeste_treptele_cautiunii()
        return self._trepte_cautiune

    def _citeste_treptele_cautiunii(self) -> list[Treapta]:
        temei = Temei("719", "2", act=CPC)
        text_alineat = self.text(temei)
        articol = self.cpc.articol("719")
        litere = [(k.split("|")[1], t) for k, t in articol.fragmente.items() if k.startswith("2|") and k != "2|"]
        if not litere:
            raise CifreIlizibile(temei, text_alineat, "nu mai găsesc literele cu treptele cauțiunii.")
        trepte = []
        for litera, text in litere:
            s = _simplu(text)
            if m := re.match(rf"de {_PROCENT},? daca aceasta valoare este pana la {_LEI}", s):
                trepte.append(Treapta(litera, Decimal(0), _decimal(*m.group(3, 4)), Decimal(0),
                                      _decimal(*m.group(1, 2)), Decimal(0)))
            elif m := re.match(rf"de {_LEI} plus {_PROCENT} pentru ceea ce depaseste {_LEI}", s):
                prag = _decimal(*m.group(5, 6))
                trepte.append(Treapta(litera, prag, None, _decimal(*m.group(1, 2)), _decimal(*m.group(3, 4)), prag))
            else:
                raise CifreIlizibile(Temei("719", "2", litera, CPC), text, "forma treptei s-a schimbat.")
        for anterioara, urmatoarea in zip(trepte, trepte[1:]):
            anterioara.pana_la = anterioara.pana_la if anterioara.pana_la is not None else urmatoarea.de_la
            if anterioara.pana_la != urmatoarea.de_la:
                raise CifreIlizibile(temei, text_alineat, f"treptele lit. {anterioara.litera}) și "
                                                          f"lit. {urmatoarea.litera}) nu se mai continuă.")
        if len(trepte) < 2 or trepte[0].de_la != 0 or trepte[-1].pana_la is not None:
            raise CifreIlizibile(temei, text_alineat, "treptele nu mai acoperă toate valorile.")
        return trepte


# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
# Calculul
# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────

@dataclass
class Rezultat:
    suma: Decimal
    pasi: list[str] = field(default_factory=list)       # cum s-a ajuns la sumă, cu temeiul fiecărui pas

    def __post_init__(self):
        self.suma = _rotunjeste(Decimal(self.suma))


def taxa_art3(texte: TexteLegale, valoare: Decimal, ce: str = "") -> Rezultat:
    """Taxa după treptele art. 3 alin. (1), la valoarea dată."""
    return _pe_trepte(texte.trepte(), valoare, lambda litera: Temei("3", "1", litera), "Taxa", ce)


def cautiune_719(texte: TexteLegale, valoare: Decimal) -> Rezultat:
    """Cauțiunea după treptele art. 719 alin. (2) C.pr.civ., la valoarea obiectului."""
    return _pe_trepte(texte.trepte_cautiune(), valoare, lambda litera: Temei("719", "2", litera, CPC), "Cauțiunea")


def _pe_trepte(trepte: list[Treapta], valoare: Decimal, temei_literei, ce_e: str, ce: str = "") -> Rezultat:
    valoare = Decimal(valoare)
    if valoare <= 0:
        raise ValueError("Valoarea trebuie să fie mai mare decât 0.")
    treapta = next(t for t in trepte if t.pana_la is None or valoare <= t.pana_la)
    temei = temei_literei(treapta.litera)
    eticheta = f"{ce_e} la {lei(valoare)}{f' ({ce})' if ce else ''}, {temei}"
    if treapta.fix == 0 and treapta.peste == 0:
        taxa = valoare * treapta.procent / 100
        pas = f"{eticheta}: {_procent(treapta.procent)} × {lei(valoare)} = {lei(taxa)}"
        if taxa < treapta.minim:
            taxa = treapta.minim
            pas += f", dar nu mai puțin de {lei(treapta.minim)}"
        return Rezultat(taxa, [pas])
    taxa = treapta.fix + (valoare - treapta.peste) * treapta.procent / 100
    return Rezultat(taxa, [f"{eticheta}: {lei(treapta.fix)} + {_procent(treapta.procent)} × ({lei(valoare)} − "
                           f"{lei(treapta.peste)}) = {lei(taxa)}"])


@dataclass(frozen=True)
class Intrare:
    cheie: str
    eticheta: str
    tip: str = "lei"                   # „lei” (sumă, cu zecimale) sau „numar” (bucăți, întreg ≥ 1)
    implicit: str = ""


VALOARE = Intrare("valoare", "Valoarea (lei)")
TAXA, CAUTIUNE = "taxa", "cautiune"


@dataclass(frozen=True)
class Caz:
    """Un tip de cerere: unde e în lege, ce date cere și cum se calculează din cifrele citite."""
    cheie: str
    grup: str
    eticheta: str
    temeiuri: tuple[Temei, ...]                                         # punctele arătate lângă rezultat
    intrari: tuple[Intrare, ...]
    calculeaza: Callable[[TexteLegale, dict], Rezultat]
    # Ce trebuie să conțină punctul (fără diacritice, litere mici): primul temei, dacă nu se spune altul
    reper: str = ""
    temei_reper: Temei | None = None
    fel: str = TAXA                     # taxă de timbru sau cauțiune (nu se adună laolaltă)
    plafon: bool = False                # rezultatul e doar maximul legal (cuantumul îl fixează instanța)

    def aplica(self, texte: TexteLegale, valori: dict) -> Rezultat:
        """Taxa, după ce s-a verificat că punctul privește tot cazul ales."""
        if self.reper:
            texte.verifica_reperul(self.temei_reper or self.temeiuri[0], self.reper)
        return self.calculeaza(texte, valori)

    def verifica(self, texte: TexteLegale) -> CifreIlizibile | None:
        """Dacă cifrele cazului se pot citi din forma dată (cu date de probă); altfel problema."""
        proba = {i.cheie: (Decimal(1000) if i.tip == "lei" else 1) for i in self.intrari}
        try:
            self.aplica(texte, proba)
        except CifreIlizibile as e:
            return e
        return None


def _r(caz: Caz, reper: str, temei: Temei | None = None) -> Caz:
    """Cazul, cu reperul punctului lui (vezi Caz.reper)."""
    from dataclasses import replace
    return replace(caz, reper=reper, temei_reper=temei)


def _valoare(valori: dict, cheie: str = "valoare") -> Decimal:
    v = Decimal(valori[cheie])
    if v <= 0:
        raise ValueError("Valoarea trebuie să fie mai mare decât 0.")
    return v


def _bucati(valori: dict, cheie: str) -> int:
    n = int(valori[cheie])
    if n < 1:
        raise ValueError("Numărul trebuie să fie cel puțin 1.")
    return n


# Fabricile cazurilor ─────────────────────────────────────────────────────────────────────────────────────────────────

def _fix(cheie, grup, eticheta, temei: Temei, *, arata: Temei | None = None, index=0, cate=1) -> Caz:
    """Sumă fixă: a `index`-a dintre cele `cate` sume în lei ale punctului."""
    def calc(o, v):
        suma = o.sume(temei, cate)[index]
        return Rezultat(suma, [f"{arata or temei}: {lei(suma)}"])
    return Caz(cheie, grup, eticheta, (arata or temei,) if arata is None or arata == temei else (arata, temei), (),
               calc)


def _per_bucata(cheie, grup, eticheta, temei: Temei, intrare: Intrare, *, index=0, cate=1,
                a_doua: Intrare | None = None) -> Caz:
    """Sumă pe bucată (participant, motiv, pagină, exemplar, titlu); cu `a_doua`, înmulțită și cu ea."""
    def calc(o, v):
        suma = o.sume(temei, cate)[index]
        n = _bucati(v, intrare.cheie)
        m = _bucati(v, a_doua.cheie) if a_doua else 1
        detaliu = f"{lei(suma)} × {n}" + (f" × {m}" if a_doua else "")
        return Rezultat(suma * n * m, [f"{temei}: {detaliu} = {lei(suma * n * m)}"])
    return Caz(cheie, grup, eticheta, (temei,), (intrare,) + ((a_doua,) if a_doua else ()), calc)


# Între prag și a doua sumă pot fi alte numere cu punct („sau valoarea în euro nu depășește … 2.000 lei”), deci nu
# „[^.]”: prima apariție a lui „nu depășește” dă pragul, prima apariție a lui „și cu” dă a doua sumă
_MODEL_PRAG = rf"cu {_LEI},? daca valoarea .*? nu depaseste {_LEI}.*? si cu {_LEI}"


def _prag(cheie, grup, eticheta, temei: Temei) -> Caz:
    """„cu X lei, dacă valoarea … nu depășește P lei, și cu Y lei, pentru … peste” (aceeași formulare în mai multe
    puncte)."""
    def calc(o, v):
        m = o.potrivire(temei, _MODEL_PRAG, "pragul și cele două sume")
        sub, prag, peste = _decimal(*m.group(1, 2)), _decimal(*m.group(3, 4)), _decimal(*m.group(5, 6))
        valoare = _valoare(v)
        suma = sub if valoare <= prag else peste
        relatie = "nu depășește" if valoare <= prag else "depășește"
        return Rezultat(suma, [f"{temei}: valoarea de {lei(valoare)} {relatie} {lei(prag)} → {lei(suma)}"])
    return Caz(cheie, grup, eticheta, (temei,), (VALOARE,), calc)


def _art3(cheie, grup, eticheta, arata: Temei | None = None, *, intrare: Intrare = VALOARE) -> Caz:
    """Taxa după treptele art. 3 alin. (1), la valoarea cererii."""
    def calc(o, v):
        return taxa_art3(o, _valoare(v, intrare.cheie))
    temeiuri = ((arata,) if arata else ()) + (Temei("3", "1"),)      # punctul propriu întâi (îl arată lista)
    return Caz(cheie, grup, eticheta, temeiuri, (intrare,), calc)


def _art3_din_procent(cheie, grup, eticheta, temei: Temei, *, index=0, cate=1) -> Caz:
    """Art. 4: taxa după art. 3 alin. (1), la un procent din valoarea bunului."""
    def calc(o, v):
        p = o.procente(temei, cate)[index]
        valoare = _valoare(v)
        baza = valoare * p / 100
        r = taxa_art3(o, baza)
        return Rezultat(r.suma, [f"{temei}: valoarea taxabilă = {_procent(p)} × {lei(valoare)} = {lei(baza)}"]
                        + r.pasi)
    return Caz(cheie, grup, eticheta, (temei, Temei("3", "1")), (Intrare("valoare", "Valoarea bunului (lei)"),), calc)


def _fractia_partajului(o: TexteLegale) -> tuple[Decimal, str]:
    """Art. 5 alin. (1): „cu jumătate din taxa stabilită potrivit art. 3” (sau un procent, dacă textul se schimbă)."""
    temei = Temei("5", "1")
    s = _simplu(o.text(temei))
    if re.search(r"se taxeaza cu jumatate din taxa", s):
        return Decimal("0.5"), "jumătate"
    if m := re.search(rf"se taxeaza cu {_PROCENT} din taxa", s):
        p = _decimal(*m.group(1, 2))
        return p / 100, _procent(p)
    raise CifreIlizibile(temei, o.text(temei), "nu mai găsesc partea din taxa art. 3 care se datorează la partaj.")


def taxa_partaj(o: TexteLegale, valoare: Decimal) -> Rezultat:
    fractie, cum = _fractia_partajului(o)
    r = taxa_art3(o, valoare)
    taxa = r.suma * fractie
    return Rezultat(taxa, r.pasi + [f"art. 5 alin. (1): {cum} din {lei(r.suma)} = {lei(taxa)}"])


def _apel(cheie, eticheta, intrare: Intrare, *, din_art3: bool) -> Caz:
    """Art. 23 alin. (1): procentul din alineat (din taxa de la fond), dar nu mai puțin de minimul literei."""
    def calc(o, v):
        p = o.procente(Temei("23", "1"), 1)[0]
        minim = o.suma(Temei("23", "1", "b" if din_art3 or intrare.cheie == "taxa_evaluabil" else "a"))
        if din_art3:
            r = taxa_art3(o, _valoare(v, intrare.cheie), "suma contestată")
            baza, pasi = r.suma, r.pasi
        else:
            baza, pasi = _valoare(v, intrare.cheie), []
        taxa = baza * p / 100
        pas = f"art. 23 alin. (1): {_procent(p)} × {lei(baza)} = {lei(taxa)}"
        if taxa < minim:
            taxa = minim
            pas += f", dar nu mai puțin de {lei(minim)}"
        return Rezultat(taxa, pasi + [pas])
    return Caz(cheie, "Căi de atac", eticheta, (Temei("23", "1"),) + ((Temei("3", "1"),) if din_art3 else ()),
               (intrare,), calc)


def _recurs_drept_material(cheie, eticheta, intrare: Intrare, *, din_art3: bool) -> Caz:
    """Art. 24 alin. (2), cereri evaluabile: procent din taxa la suma contestată, dar nu mai puțin de minim."""
    temei = Temei("24", "2")

    def calc(o, v):
        p = o.procente(temei, 1)[0]
        minim = o.sume(temei, 2)[0]
        if din_art3:
            r = taxa_art3(o, _valoare(v, intrare.cheie), "suma contestată")
            baza, pasi = r.suma, r.pasi
        else:
            baza, pasi = _valoare(v, intrare.cheie), []
        taxa = baza * p / 100
        pas = f"{temei}: {_procent(p)} × {lei(baza)} = {lei(taxa)}"
        if taxa < minim:
            taxa = minim
            pas += f", dar nu mai puțin de {lei(minim)}"
        return Rezultat(taxa, pasi + [pas])
    return Caz(cheie, "Căi de atac", eticheta, (temei,) + ((Temei("3", "1"),) if din_art3 else ()), (intrare,), calc)


def _calc_granituire(o, v):
    temei = Temei("8", "1")
    suma = o.suma(temei)
    pasi = [f"{temei} lit. d): {lei(suma)}"]
    revendicat = Decimal(v.get("valoare_revendicata") or 0)
    if revendicat > 0:
        r = taxa_art3(o, revendicat, "suprafața revendicată")
        return Rezultat(suma + r.suma, pasi + r.pasi + [f"Total: {lei(suma)} + {lei(r.suma)} = {lei(suma + r.suma)}"])
    return Rezultat(suma, pasi)


def _calc_contestatie_executare(o, v):
    temei = Temei("10", "2")
    plafon = _decimal(*o.potrivire(temei, rf"nu poate depasi suma de {_LEI}", "plafonul contestației").group(1, 2))
    r = taxa_art3(o, _valoare(v))
    if r.suma > plafon:
        return Rezultat(plafon, r.pasi + [f"{temei}: taxa nu poate depăși {lei(plafon)} → {lei(plafon)}"])
    return Rezultat(r.suma, r.pasi + [f"{temei}: sub plafonul de {lei(plafon)}"])


def _calc_contestatie_neevaluabila(o, v):
    temei = Temei("10", "2")
    suma = _decimal(*o.potrivire(temei, rf"nu este evaluabil in bani,? contestatia la executare se taxeaza cu {_LEI}",
                                 "taxa contestației neevaluabile").group(1, 2))
    return Rezultat(suma, [f"{temei}, teza a III-a: {lei(suma)}"])


def _calc_ordonanta_presedintiala_neevaluabila(o, v):
    temei = Temei("6", "4")
    suma = _decimal(*o.potrivire(temei, rf"neevaluabile in bani,? se taxeaza cu {_LEI}",
                                 "taxa ordonanței președințiale neevaluabile").group(1, 2))
    return Rezultat(suma, [f"{temei}: {lei(suma)}"])


def _calc_invoiala_imobil(o, v):
    temei = Temei("11", "1", "a")
    fix = _decimal(*o.potrivire(temei, rf"^[^;]*? - {_LEI}", "taxa fixă a învoielii").group(1, 2))
    p = o.procente(temei, 2)[0]
    r = taxa_art3(o, _valoare(v), "revendicarea bunului cel mai valoros")
    adaos = r.suma * p / 100
    return Rezultat(fix + adaos, r.pasi + [f"{temei}: {lei(fix)} + {_procent(p)} × {lei(r.suma)} = {lei(fix + adaos)}"])


def _calc_invoiala_partaj(o, v):
    temei = Temei("11", "1", "a")
    fix = _decimal(*o.potrivire(temei, rf"^[^;]*? - {_LEI}", "taxa fixă a învoielii").group(1, 2))
    p = o.procente(temei, 2)[1]
    r = taxa_partaj(o, _valoare(v))
    adaos = r.suma * p / 100
    return Rezultat(fix + adaos, r.pasi + [f"{temei}: {lei(fix)} + {_procent(p)} × {lei(r.suma)} = {lei(fix + adaos)}"])


def _calc_invoiala_simpla(o, v):
    temei = Temei("11", "1", "a")
    fix = _decimal(*o.potrivire(temei, rf"^[^;]*? - {_LEI}", "taxa fixă a învoielii").group(1, 2))
    return Rezultat(fix, [f"{temei}: {lei(fix)}"])


def _calc_contencios_patrimonial(o, v):
    temei = Temei("16", "", "b")
    m = o.potrivire(temei, rf"{_PROCENT} din valoarea pretinsa,? dar nu mai mult de {_LEI}", "procentul și plafonul")
    p, plafon = _decimal(*m.group(1, 2)), _decimal(*m.group(3, 4))
    valoare = _valoare(v)
    taxa = valoare * p / 100
    pas = f"{temei}: {_procent(p)} × {lei(valoare)} = {lei(taxa)}"
    if taxa > plafon:
        taxa = plafon
        pas += f", dar nu mai mult de {lei(plafon)}"
    return Rezultat(taxa, [pas])


def _calc_repunere_pe_rol(o, v):
    temei = Temei("9", "", "g")
    p = o.procente(temei, 1)[0]
    baza = _valoare(v, "taxa_suspendata")
    return Rezultat(baza * p / 100, [f"{temei}: {_procent(p)} × {lei(baza)} = {lei(baza * p / 100)}"])


def _calc_partaj(o, v):
    return taxa_partaj(o, _valoare(v))


def _calc_recurs_neevaluabil(o, v):
    temei = Temei("24", "2")
    suma = o.sume(temei, 2)[1]
    return Rezultat(suma, [f"{temei}, teza a II-a: {lei(suma)}"])


TAXA_FOND = Intrare("taxa_fond", "Taxa datorată la fond (lei)")
SUMA_CONTESTATA = Intrare("suma_contestata", "Suma contestată (lei)")
TAXA_EVALUABIL = Intrare("taxa_evaluabil", "Taxa datorată la suma contestată (lei)")


# Cauțiunile (Codul de procedură civilă) ──────────────────────────────────────────────────────────────────────────────

GRUP_CAUTIUNI = "Cauțiuni (Codul de procedură civilă)"


def _cautiune(caz: Caz) -> Caz:
    from dataclasses import replace
    return replace(caz, fel=CAUTIUNE)


def _verifica_trimiterile(o: TexteLegale, trimiteri) -> list[str]:
    """Articolele care trimit la cauțiunea altui articol trebuie să trimită tot acolo (altfel cauțiunea lor s-a
    schimbat și nu se mai calculează după regula din cod)."""
    pasi = []
    for temei, reper, la_ce in trimiteri:
        text = o.text(temei)
        if not re.search(reper, _simplu(text)):
            raise CifreIlizibile(temei, text, f"în {o.forma_pentru(temei)} nu mai trimite la {la_ce}.")
        pasi.append(f"{temei} trimite la {la_ce}")
    return pasi


def _caz_cautiune_719(cheie, eticheta, trimiteri=(), intrare="Valoarea obiectului (lei)") -> Caz:
    """Cauțiunea după treptele art. 719 alin. (2), direct sau prin trimiterea altui articol."""
    def calc(o, v):
        pasi = _verifica_trimiterile(o, trimiteri)
        r = cautiune_719(o, _valoare(v))
        return Rezultat(r.suma, pasi + r.pasi)
    temeiuri = tuple(t for t, _r_, _c in trimiteri) + (Temei("719", "2", act=CPC),)
    return Caz(cheie, GRUP_CAUTIUNI, eticheta, temeiuri, (Intrare("valoare", intrare),), calc, fel=CAUTIUNE)


def _calc_cautiune_recuzare_executor(o, v):
    temei = Temei("653", "2", act=CPC)
    m = o.potrivire(temei, rf"cautiune in cuantum de {_LEI}.*? nu depaseste {_LEI},? cautiunea va fi de {_PROCENT}",
                    "cauțiunea, pragul și procentul")
    fix, prag, p = _decimal(*m.group(1, 2)), _decimal(*m.group(3, 4)), _decimal(*m.group(5, 6))
    creanta = _valoare(v)
    if creanta <= prag:
        suma = creanta * p / 100
        return Rezultat(suma, [f"{temei}: creanța de {lei(creanta)} nu depășește {lei(prag)} → "
                               f"{_procent(p)} × {lei(creanta)} = {lei(suma)}"])
    return Rezultat(fix, [f"{temei}: creanța de {lei(creanta)} depășește {lei(prag)} → {lei(fix)}"])


def _calc_cautiune_sechestru(o, v):
    temei = Temei("953", "2", act=CPC)
    s = _simplu(o.text(temei))
    if re.search(r"cautiune de jumatate din valoarea reclamata", s):
        fractie, cum = Decimal("0.5"), "jumătate"
    elif m := re.search(rf"cautiune de {_PROCENT} din valoarea reclamata", s):
        p = _decimal(*m.group(1, 2))
        fractie, cum = p / 100, _procent(p)
    else:
        raise CifreIlizibile(temei, o.text(temei), "nu mai găsesc partea din valoarea reclamată.")
    valoare = _valoare(v)
    return Rezultat(valoare * fractie, [f"{temei}: {cum} din {lei(valoare)} = {lei(valoare * fractie)}"])


def _calc_cautiune_valoare_redusa(o, v):
    temei = Temei("1033", "2", act=CPC)
    p = _decimal(*o.potrivire(temei, rf"cautiune de {_PROCENT} din valoarea contestata", "procentul").group(1, 2))
    valoare = _valoare(v)
    return Rezultat(valoare * p / 100, [f"{temei}: {_procent(p)} × {lei(valoare)} = {lei(valoare * p / 100)}"])


def _calc_plafon_evaluabil(o, v):
    temei = Temei("1057", "2", act=CPC)
    p = _decimal(*o.potrivire(temei, rf"nu va reprezenta mai mult de {_PROCENT} din valoarea obiectului",
                              "procentul maxim").group(1, 2))
    valoare = _valoare(v)
    return Rezultat(valoare * p / 100, [f"{temei}: cel mult {_procent(p)} × {lei(valoare)} = "
                                        f"{lei(valoare * p / 100)}; cuantumul îl fixează instanța"])


def _calc_plafon_neevaluabil(o, v):
    temei = Temei("1057", "2", act=CPC)
    suma = _decimal(*o.potrivire(temei, rf"nu va putea depasi suma de {_LEI}", "suma maximă").group(1, 2))
    return Rezultat(suma, [f"{temei}: cel mult {lei(suma)}; cuantumul îl fixează instanța"])


def _cautiunile() -> list[Caz]:
    T, c = Temei, GRUP_CAUTIUNI
    la_719 = "cauțiunea de la art. 719 C.pr.civ."
    la_484 = "art. 484 C.pr.civ. (cauțiunea de la art. 719)"
