def id_ordonanta() -> int:
    """Id-ul paginii OUG 80/2013: cel din dicționarul de legi, dacă judecătorul l-a pus acolo; altfel cel știut."""
    try:
        import dictionar_legi as dl
        intrare = dl.gaseste(dl.incarca(), NUME_ORDONANTA)
        if intrare is not None and intrare.id:
            return intrare.id
    except Exception:
        log.warning("Dicționarul de legi nu s-a putut citi; OUG 80/2013 se ia după id-ul știut", exc_info=True)
    return ID_OUG_80_2013


def id_cpc() -> int:
    """Id-ul paginii Codului de procedură civilă: cel de pe pagina principală a portalului (vezi dicționarul)."""
    return portal.id_coduri().get(portal.COD_PROCEDURA_CIVILA) or portal.ID_CODURI_IMPLICITE[portal.COD_PROCEDURA_CIVILA]


