    if reimprospateaza:
        portal.obtine_act(id_act, reimprospateaza=True)
    return portal.obtine_forma_la_data(id_act, la_data)


def incarca_textele(la_data: datetime.date | None = None, *, reimprospateaza: bool = False,
                    forma_la_data: Callable[[int, datetime.date], portal.ActLegislativ | None] | None = None,
                    id_oug: int | None = None, id_cod: int | None = None) -> TexteLegale:
    """OUG 80/2013 și Codul de procedură civilă în forma în vigoare la `la_data` (implicit azi). Cu `reimprospateaza`,
    paginile se descarcă din nou înainte (o consolidare nouă apare imediat, nu după cele 7 zile de păstrare pe disc).
    Fără ordonanță: TexteIndisponibile. Fără Cod: doar cauțiunile refuză calculul, cu motivul.

    `forma_la_data(id, zi)` (cu `id_oug` și `id_cod`) dă formele din altă parte decât portalul: Mercurius fără
    calculator le ia din pachetul de texte de pe telefon (mercurius_telefon)."""
    la_data = la_data or datetime.date.today()
    if forma_la_data is None:
        def forma_la_data(id_act, zi):
            return _forma_la_data(id_act, zi, reimprospateaza)
    try:
        act = forma_la_data(id_oug or id_ordonanta(), la_data)
    except portal.EroarePortal as e:
        raise TexteIndisponibile(f"Textul OUG 80/2013 nu se poate obține: {e}") from e
    if act is None:
        raise TexteIndisponibile(f"Pentru {la_data:%d.%m.%Y} istoricul consolidărilor de pe portal nu are o formă "
                                 "a OUG 80/2013 (data e dinaintea primei consolidări).")
    if not act.articole or not portal._titlul_are_numarul(act.titlu, "80", "2013"):
        raise TexteIndisponibile(f"Pagina {act.url} nu are textul OUG 80/2013 („{act.titlu or 'fără titlu'}”). "
                                 "Verifică id-ul în Configurare → Dicționarul de legi.")
    cpc, problema = None, ""
    try:
        cpc = forma_la_data(id_cod or id_cpc(), la_data)
        if cpc is None:
            problema = f"istoricul consolidărilor nu are o formă pentru {la_data:%d.%m.%Y}"
        elif not cpc.articole or "procedura civila" not in _simplu(cpc.titlu):
            problema, cpc = f"pagina {cpc.url} nu are textul Codului („{cpc.titlu}”)", None
    except portal.EroarePortal as e:
        problema = str(e)
    if problema:
        log.warning("Codul de procedură civilă nu s-a citit pentru cauțiuni: %s", problema)
    return TexteLegale(act, cpc, problema_cpc=problema)


def calculeaza(caz: Caz | str, valori: dict, texte: TexteLegale) -> Rezultat:
    """Suma pentru cazul dat; ValueError la date greșite, CifreIlizibile când punctul nu se mai poate citi."""
    caz = CAZURI_DUPA_CHEIE[caz] if isinstance(caz, str) else caz
    return caz.aplica(texte, valori)


# Textele de copiat (fereastra calculatorului și Mercurius, pe telefon) ──────────────────────────────────────────────

def ce_suma(caz: Caz) -> str:
    return "cauțiune" if caz.fel == CAUTIUNE else "taxă judiciară de timbru"


def formele_cazului(texte: TexteLegale, caz: Caz) -> str:
    """„OUG nr. 80/2013, forma consolidată la …; Codul de procedură civilă, forma consolidată la …” (actele cazului)."""
    acte = list(dict.fromkeys(t.act for t in caz.temeiuri))
    return "; ".join(f"{NUME_ACTE[a]}, {texte.forma if a == OUG else texte.forma_cpc}" for a in acte)


def text_rezultat(caz: Caz, rezultat: Rezultat, texte: TexteLegale) -> str:
    """Suma, pașii și forma legii, ca text simplu (pentru încheiere, rezoluție, notă)."""
    suma = (f"cauțiune — plafonul legal: cel mult {lei(rezultat.suma)}" if caz.plafon
            else f"{ce_suma(caz)} {lei(rezultat.suma)}")
    return f"{caz.eticheta}: {suma}\n" + "\n".join(rezultat.pasi) + f"\n({formele_cazului(texte, caz)})"


def text_rand(r: "RandNota") -> str:
    calculat, datorat = r.capat.rezultat.suma, r.datorat
    ce = "cauțiune " if r.capat.caz.fel == CAUTIUNE else ""
    suma = lei(datorat) if datorat == calculat else f"{lei(calculat)} → {lei(datorat)}"
    return f"{r.capat.caz.eticheta} — {ce}{suma}" + (f"  ({r.mentiune})" if r.mentiune else "")


def text_nota(nota: "NotaTimbraj", texte: TexteLegale | None) -> str:
    linii = [text_rand(r) for r in nota.randuri]
    linii.append(f"Total taxă judiciară de timbru: {lei(nota.total_taxe)}")
    if any(r.capat.caz.fel == CAUTIUNE for r in nota.randuri):
        linii.append(f"Total cauțiuni: {lei(nota.total_cautiuni)}")
    linii += [f"⚠ {a}" for a in nota.avertismente]
    if texte is not None:
        linii.append(f"(OUG nr. 80/2013, {texte.forma}; Codul de procedură civilă, {texte.forma_cpc})")
    return "\n".join(linii)


# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
# Nota de timbraj: capetele aceleiași cereri, cu regulile ordonanței despre cererile accesorii
# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────

@dataclass
class Capat:
    """Un capăt de cerere adăugat în notă: cazul, datele lui și suma calculată singur."""
    caz: Caz
    valori: dict
    rezultat: Rezultat


@dataclass
class RandNota:
    capat: Capat
    datorat: Decimal                    # după regulile notei (0 pentru un capăt accesoriu, scutit sau inclus)
    mentiune: str = ""


@dataclass
class NotaTimbraj:
    randuri: list[RandNota]
    avertismente: list[str] = field(default_factory=list)

    @property
    def total_taxe(self) -> Decimal:
        return sum((r.datorat for r in self.randuri if r.capat.caz.fel == TAXA), Decimal(0))

    @property
    def total_cautiuni(self) -> Decimal:
        return sum((r.datorat for r in self.randuri if r.capat.caz.fel == CAUTIUNE), Decimal(0))


DIVORT = ("art15a", "art15b")
PARTAJ = ("art5_1",)


def _regula_se_gaseste(texte: TexteLegale, temei: Temei, model: str, nota: NotaTimbraj, ce: str) -> bool:
    """Regula se aplică doar dacă textul ei e tot în lege; altfel nota spune că s-a adunat fără ea."""
    try:
        text = texte.text(temei)
    except CifreIlizibile:
        text = ""
    if re.search(model, _simplu(text)):
        return True
    nota.avertismente.append(f"Regula de la {temei} ({ce}) nu se mai găsește în {texte.forma_pentru(temei)}; "
                             "capetele s-au adunat fără ea.")
    return False


def nota_de_timbraj(capete: list[Capat], texte: TexteLegale, *, victima_violenta: bool = False) -> NotaTimbraj:
    """Capetele aceleiași acțiuni (art. 34 alin. (1): taxa se datorează pentru fiecare capăt), cu regulile ordonanței:

    • art. 15 lit. d): cererile privind copilul și locuința familiei se taxează separat (20 lei fiecare) numai dacă nu
      sunt accesorii divorțului; alături de divorț (art. 15 lit. a) sau b)) intră în taxa divorțului;
    • art. 3 alin. (2) lit. a): repunerea în situația anterioară e scutită când e accesorie cererii în nulitate /
      anulare / rezoluțiune / reziliere;
    • art. 5 alin. (2): cererile de partaj din aceeași acțiune se taxează cu o singură taxă, la valoarea cea mai mare;
    • art. 29 alin. (6): divorțul și partajul sunt scutite când le formulează victima violenței în familie (bifa notei).
    """
    nota = NotaTimbraj([RandNota(c, c.rezultat.suma) for c in capete])
    chei = [r.capat.caz.cheie for r in nota.randuri]

    if victima_violenta and any(k in DIVORT + PARTAJ for k in chei) and _regula_se_gaseste(
            texte, Temei("29", "6"), r"divort si partaj.*violenta in familie", nota, "scutirea victimelor"):
        for r in nota.randuri:
            if r.capat.caz.cheie in DIVORT + PARTAJ:
                r.datorat, r.mentiune = Decimal(0), "scutit — victimă a violenței în familie (art. 29 alin. (6))"

    if any(k in DIVORT for k in chei) and "art15d" in chei and _regula_se_gaseste(
            texte, Temei("15", "", "d"), r"nu sunt accesorii unei cereri de divort", nota, "cererile accesorii divorțului"):
        for r in nota.randuri:
            if r.capat.caz.cheie == "art15d":
                r.datorat = Decimal(0)
                r.mentiune = ("accesoriu divorțului — inclus în taxa divorțului (art. 15 lit. d) taxează numai "
                              "cererile neaccesorii)")

    if "art3_2a" in chei and "art8_2" in chei and _regula_se_gaseste(
            texte, Temei("3", "2", "a"), r"repunerea partilor in situatia anterioara este scutita .*accesorie", nota,
            "repunerea accesorie"):
        for r in nota.randuri:
            if r.capat.caz.cheie == "art8_2":
                r.datorat = Decimal(0)
                r.mentiune = "scutită — accesorie cererii în nulitate / anulare / rezoluțiune / reziliere (art. 3 alin. (2) lit. a))"

    partaje = [r for r in nota.randuri if r.capat.caz.cheie in PARTAJ and not r.mentiune]
    if len(partaje) > 1 and _regula_se_gaseste(texte, Temei("5", "2"), r"o singura taxa.*valoarea cea mai mare", nota,
                                               "taxa unică la partaj"):
        cel_mai_mare = max(partaje, key=lambda r: Decimal(r.capat.valori.get("valoare", 0)))
        for r in partaje:
            if r is not cel_mai_mare:
                r.datorat = Decimal(0)
                r.mentiune = "inclus — o singură taxă, la valoarea cea mai mare (art. 5 alin. (2))"
        cel_mai_mare.mentiune = "taxa unică a partajului (art. 5 alin. (2))"
    return nota

fisiere.companion_taxe.py:
"""
Mercurius → 🧮 Taxe: calculatorul taxelor de timbru și cauțiunilor (taxa_timbru) pentru pagina de pe telefon.

Aceleași cazuri, aceleași cifre citite din forma legii în vigoare la data cererii și aceleași reguli ale notei de
timbraj ca în fereastra Unelte → 🧮 Taxe și cauțiuni; aici doar se traduc în JSON. Textele legii se citesc o dată pe
dată (paginile portalului stau pe disc 7 zile, ca pe PC) și se țin în memorie o oră. Fără Qt.
"""

from __future__ import annotations

import datetime
import threading
import time
import weakref
from decimal import InvalidOperation
from typing import Callable, Dict, Optional, Tuple

import taxa_timbru as tt
from companion import EroareCompanion
from logger import get_logger

log = get_logger(__name__)

_PASTRARE_S = 3600
_MAX_CAPETE = 40


class _Incomplet(ValueError):
    """Un câmp al cazului e gol: pe telefon nu e o eroare, doar „completează”."""


def _data(text: str) -> datetime.date:
    if not text:
        return datetime.date.today()
    try:
        return datetime.date.fromisoformat(str(text)[:10])
    except ValueError:
        raise EroareCompanion("Data cererii nu e validă.")


def _suma_afisata(caz: tt.Caz, rezultat: tt.Rezultat) -> str:
    if caz.plafon:
        return f"cel mult {tt.lei(rezultat.suma)}"
    return tt.lei(rezultat.suma)


class CalculatorTaxe:
    def __init__(self, incarca: Callable[[datetime.date], tt.TexteLegale] = None):
        self._incarca = incarca or (lambda zi: tt.incarca_textele(zi))
        self._lock = threading.RLock()
        self._texte: Dict[datetime.date, Tuple[float, object]] = {}
        self._in_curs: Dict[datetime.date, threading.Lock] = {}
        self._verificari: "weakref.WeakKeyDictionary[tt.TexteLegale, Dict[str, str]]" = weakref.WeakKeyDictionary()

    # -- textele legii -------------------------------------------------------------

    def texte(self, zi: datetime.date) -> tt.TexteLegale:
        """Forma legii la `zi`; o singură citire odată pentru aceeași zi, chiar dacă întreabă mai multe cereri."""
        with self._lock:
            intrare = self._texte.get(zi)
            if intrare and time.monotonic() - intrare[0] < _PASTRARE_S:
                return self._rezultat(intrare[1])
            lacat = self._in_curs.setdefault(zi, threading.Lock())
        with lacat:
            with self._lock:
                intrare = self._texte.get(zi)
                if intrare and time.monotonic() - intrare[0] < _PASTRARE_S:
                    return self._rezultat(intrare[1])
            try:
                rezultat = self._incarca(zi)
            except tt.TexteIndisponibile as e:
                rezultat = e
            except Exception as e:          # portalul căzut, pagină stricată: mesajul ajunge pe telefon
                log.warning("Mercurius: textele legii pentru %s nu s-au citit", zi, exc_info=True)
                rezultat = tt.TexteIndisponibile(f"Textele legii nu s-au putut citi: {e}")
            with self._lock:
                # o eroare nu se ține o oră: la următoarea cerere se reîncearcă
                self._texte[zi] = (time.monotonic() if isinstance(rezultat, tt.TexteLegale)
                                   else time.monotonic() - _PASTRARE_S + 60, rezultat)
            return self._rezultat(rezultat)

    @staticmethod
    def _rezultat(r):
        if isinstance(r, Exception):
            raise EroareCompanion(str(r), 503)
        return r

    def _probleme(self, texte: tt.TexteLegale) -> Dict[str, str]:
        """Cazurile ale căror cifre nu se pot citi din forma dată (gri pe telefon, ca în fereastră), cu motivul."""
        with self._lock:
            gata = self._verificari.get(texte)
            if gata is not None:
                return gata
            probleme = {}
            for caz in tt.CAZURI:
                problema = caz.verifica(texte)
                if problema:
                    probleme[caz.cheie] = f"{problema.temei}: {problema.motiv}"
            self._verificari[texte] = probleme
            return probleme

    # -- ce vede telefonul -------------------------------------------------------------

    def raspunde(self, metoda: str, ruta: str, q: dict, corp: dict) -> dict:
        """Rutele taxe/* ale paginii, la fel prin serverul de pe calculator și în Mercurius fără calculator."""
        if metoda == "GET" and ruta == "taxe/cazuri":
            return self.cazuri(q.get("data", ""))
        if metoda == "GET" and ruta == "taxe/caz":
            return self.cazul(q.get("cheie", ""), q.get("data", ""))
        if metoda == "POST" and ruta == "taxe/calcul":
            return self.calculeaza(corp.get("cheie", ""), corp.get("valori") or {}, corp.get("data", ""))
        if metoda == "POST" and ruta == "taxe/nota":
            return self.nota(corp.get("capete") or [], bool(corp.get("victima")), corp.get("data", ""))
        raise EroareCompanion("Necunoscut.", 404)

    def cazuri(self, data: str = "") -> dict:
        zi = _data(data)
        texte = self.texte(zi)
        probleme = self._probleme(texte)
        grupe: dict = {}                    # pe grupe, în ordinea primei apariții (ca arborele din fereastră)
        for caz in tt.CAZURI:
            grupe.setdefault(caz.grup, {"nume": caz.grup, "cazuri": []})["cazuri"].append({
                "cheie": caz.cheie, "eticheta": caz.eticheta, "temei": str(caz.temeiuri[0]),
                "fel": caz.fel, "plafon": caz.plafon, "problema": probleme.get(caz.cheie, ""),
            })
        return {"data": zi.isoformat(), "forma": texte.forma,
                "forma_cpc": texte.forma_cpc if texte.cpc is not None else "",
                "problema_cpc": texte.problema_cpc if texte.cpc is None else "",
                "url": texte.act.url, "grupe": list(grupe.values()), "refuzate": len(probleme)}

    def cazul(self, cheie: str, data: str = "") -> dict:
        caz = self._caz(cheie)
        texte = self.texte(_data(data))
        return {"cheie": caz.cheie, "grup": caz.grup, "eticheta": caz.eticheta, "fel": caz.fel, "plafon": caz.plafon,
                "intrari": [{"cheie": i.cheie, "eticheta": i.eticheta, "tip": i.tip, "implicit": i.implicit}
                            for i in caz.intrari],
                "problema": self._probleme(texte).get(caz.cheie, ""),
                "lege": self._textul_legii(caz, texte)}

    @staticmethod
    def _caz(cheie: str) -> tt.Caz:
        caz = tt.CAZURI_DUPA_CHEIE.get(str(cheie))
        if caz is None:
            raise EroareCompanion("Caz necunoscut.", 404)
        return caz

    @staticmethod
    def _textul_legii(caz: tt.Caz, texte: tt.TexteLegale) -> list:
        parti = []
        for temei in caz.temeiuri:
            try:
                text = texte.text(temei)
            except tt.CifreIlizibile as e:
                text = e.text or f"({e.motiv})"
            parti.append({"temei": str(temei), "text": text})
        for act in dict.fromkeys(t.act for t in caz.temeiuri):
            a = texte.act if act == tt.OUG else texte.cpc
            parti.append({"temei": "", "text": f"{tt.NUME_ACTE[act]}, {texte.forma if act == tt.OUG else texte.forma_cpc}",
                          "url": a.url if a is not None else ""})
        return parti

    @staticmethod
    def _valori(caz: tt.Caz, valori: dict) -> dict:
        if not isinstance(valori, dict):
            raise EroareCompanion("Cerere invalidă.")
        rezultat = {}
        for intrare in caz.intrari:
            brut = str(valori.get(intrare.cheie, "") or "").strip()
            if not brut:
                raise _Incomplet(f"Completează: {intrare.eticheta}.")
            if intrare.tip == "numar":
                try:
                    rezultat[intrare.cheie] = int(brut)
                except ValueError:
                    raise ValueError(f"{intrare.eticheta}: un număr întreg.")
            else:
                try:
                    rezultat[intrare.cheie] = tt.citeste_suma(brut)
                except (ValueError, InvalidOperation):
                    raise ValueError(f"{intrare.eticheta}: o sumă în lei (ex. 12.000 sau 12.000,50).")
        return rezultat

    def calculeaza(self, cheie: str, valori: dict, data: str = "") -> dict:
        """Suma cu pașii; o problemă cu datele sau cu cifrele legii vine ca `eroare` (nu ca cerere eșuată)."""
        caz = self._caz(cheie)
        texte = self.texte(_data(data))
        try:
            v = self._valori(caz, valori)
            with self._lock:
                rezultat = tt.calculeaza(caz, v, texte)
        except _Incomplet:
            return {"eroare": "Completează datele cazului.", "incomplet": True}
        except ValueError as e:
            return {"eroare": str(e)}
        except tt.CifreIlizibile as e:
            return {"eroare": f"Nu se poate calcula automat. {e.temei}: {e.motiv} Calculează după textul punctului.",
                    "ilizibil": True}
        return {"suma": _suma_afisata(caz, rezultat), "valoare": str(rezultat.suma), "fel": caz.fel,
                "plafon": caz.plafon, "pasi": rezultat.pasi, "forme": tt.formele_cazului(texte, caz),
                "text": tt.text_rezultat(caz, rezultat, texte)}

    def nota(self, capete: list, victima_violenta: bool = False, data: str = "") -> dict:
        """Nota de timbraj a capetelor trimise de telefon ([{cheie, valori}]), cu regulile ordonanței."""
        if not isinstance(capete, list) or len(capete) > _MAX_CAPETE:
            raise EroareCompanion("Cerere invalidă.")
        texte = self.texte(_data(data))
        alese, erori = [], []
        for c in capete:
            if not isinstance(c, dict):
                raise EroareCompanion("Cerere invalidă.")
            caz = self._caz(c.get("cheie", ""))
            try:
                v = self._valori(caz, c.get("valori") or {})
                with self._lock:
                    rezultat = tt.calculeaza(caz, v, texte)
            except ValueError as e:
                erori.append(f"{caz.eticheta}: {e}")
                alese.append(None)
                continue
            except tt.CifreIlizibile as e:
                erori.append(f"{caz.eticheta}: nu se poate calcula automat ({e.temei}: {e.motiv})")
                alese.append(None)
                continue
            alese.append(tt.Capat(caz, v, rezultat) if not caz.plafon else None)
            if caz.plafon:
                erori.append(f"{caz.eticheta}: plafonul nu e o sumă datorată (cuantumul îl fixează instanța).")
        with self._lock:
            nota = tt.nota_de_timbraj([c for c in alese if c is not None], texte,
                                      victima_violenta=bool(victima_violenta))
        randuri, i = [], 0
        for c in alese:                     # rândurile, în ordinea capetelor trimise (cele refuzate: gol)
            if c is None:
                randuri.append(None)
                continue
            r = nota.randuri[i]
            i += 1
            randuri.append({"eticheta": r.capat.caz.eticheta, "fel": r.capat.caz.fel,
                            "calculat": tt.lei(r.capat.rezultat.suma), "datorat": tt.lei(r.datorat),
                            "redus": r.datorat != r.capat.rezultat.suma, "mentiune": r.mentiune})
        return {"randuri": randuri, "total_taxe": tt.lei(nota.total_taxe),
                "total_cautiuni": tt.lei(nota.total_cautiuni),
                "are_cautiuni": any(r.capat.caz.fel == tt.CAUTIUNE for r in nota.randuri),
                "avertismente": nota.avertismente + erori, "text": tt.text_nota(nota, texte)}


_calculator: Optional[CalculatorTaxe] = None
_calculator_lock = threading.Lock()


def calculatorul() -> CalculatorTaxe:
    global _calculator
    with _calculator_lock:
        if _calculator is None:
            _calculator = CalculatorTaxe()
        return _calculator

fisiere.safe_io.py:
"""
safe_io.py — Scriere atomică a fișierelor și carantinarea fișierelor necitibile.

  • atomic_write_bytes / atomic_write_text / atomic_write_json
      Scrie într-un fișier temporar din ACELAȘI folder, flush + fsync, apoi os.replace
      peste țintă. Dacă ceva eșuează, ținta rămâne neatinsă și temporarul e șters.
  • quarantine_file(path)
      Copiază un fișier necitibil/corupt în <nume>.corrupt-<YYYYmmdd_HHMMSS> ca să nu
      fie suprascris niciodată în tăcere. Returnează calea copiei sau None.

Fără dependențe din aplicație (doar biblioteca standard).
"""
import json
import logging
import os
import shutil
import tempfile
import time
from datetime import datetime

log = logging.getLogger(__name__)

_FILE_ATTRIBUTE_HIDDEN = 0x02


def _get_win_attrs(path: str) -> int:
    if os.name != 'nt':
        return -1
    try:
        import ctypes
        return ctypes.windll.kernel32.GetFileAttributesW(str(path))
    except Exception:
        return -1


def _set_win_hidden(path: str):
    try:
        import ctypes
        attrs = ctypes.windll.kernel32.GetFileAttributesW(str(path))
        if attrs != -1:
            ctypes.windll.kernel32.SetFileAttributesW(str(path), attrs | _FILE_ATTRIBUTE_HIDDEN)
    except Exception:
        log.warning("Nu am putut reface atributul 'ascuns' pentru %s", path, exc_info=True)


def _replace_with_retry(src: str, dst: str, attempts: int = 6, delay: float = 0.15):
    """os.replace cu reîncercări scurte (pe Windows ținta poate fi ținută ocupată de
    OneDrive / antivirus pentru câteva sute de ms)."""
    for i in range(attempts):
        try:
            os.replace(src, dst)
            return
        except PermissionError:
            if i == attempts - 1:
                raise
            time.sleep(delay)


def atomic_write_bytes(path: str, data: bytes):
    """Scrie atomic `data` în `path`. Ridică excepția originală la eșec (ținta rămâne intactă)."""
    path = os.path.abspath(path)
    folder = os.path.dirname(path)
    os.makedirs(folder, exist_ok=True)
    attrs = _get_win_attrs(path) if os.path.exists(path) else -1
    was_hidden = attrs != -1 and bool(attrs & _FILE_ATTRIBUTE_HIDDEN)

    fd, tmp_path = tempfile.mkstemp(prefix=f".{os.path.basename(path)}.", suffix=".tmp", dir=folder)
    try:
        with os.fdopen(fd, 'wb') as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        _replace_with_retry(tmp_path, path)
    except BaseException:
        try:
            os.remove(tmp_path)
        except OSError:
            pass
        raise
    if was_hidden:
        _set_win_hidden(path)


def atomic_write_text(path: str, text: str, encoding: str = 'utf-8'):
    atomic_write_bytes(path, text.encode(encoding))


def atomic_write_json(path: str, obj, *, ensure_ascii: bool = False, indent=None, encoding: str = 'utf-8'):
    # Serializăm complet ÎNAINTE de a atinge discul: o eroare de serializare nu lasă nimic pe jumătate.
    text = json.dumps(obj, ensure_ascii=ensure_ascii, indent=indent)
    atomic_write_text(path, text, encoding=encoding)


def _same_content(a: str, b: str) -> bool:
    try:
        if os.path.getsize(a) != os.path.getsize(b):
            return False
        with open(a, 'rb') as fa, open(b, 'rb') as fb:
            while True:
                ca, cb = fa.read(1 << 20), fb.read(1 << 20)
                if ca != cb:
                    return False
                if not ca:
                    return True
    except OSError:
        return False


def quarantine_file(path: str) -> str | None:
    """
    Copiază fișierul `path` în <path>.corrupt-<YYYYmmdd_HHMMSS> (originalul rămâne pe loc).
    Dacă există deja o copie de carantină identică, o refolosește (nu umple folderul la
    fiecare citire eșuată). Returnează calea copiei sau None dacă nu s-a putut copia.
    """
    path = os.path.abspath(path)
    if not os.path.isfile(path):
        return None
    folder = os.path.dirname(path)
    prefix = os.path.basename(path) + ".corrupt-"
    try:
        for name in sorted(os.listdir(folder)):
            if name.startswith(prefix):
                existing = os.path.join(folder, name)
                if _same_content(path, existing):
                    return existing
    except OSError:
        log.warning("Nu am putut lista %s pentru carantină", folder, exc_info=True)

    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    dest = f"{path}.corrupt-{stamp}"
    n = 1
    while os.path.exists(dest):
        dest = f"{path}.corrupt-{stamp}_{n}"
        n += 1
    try:
        shutil.copy2(path, dest)
        log.warning("Fișier necitibil pus în carantină: %s -> %s", path, dest)
        return dest
    except Exception:
        log.exception("Nu am putut pune în carantină fișierul %s", path)
        return None

fisiere.mercurius_telefon.py:
"""
mercurius_telefon.py — Mercurius fără calculator: calculatorul de taxe și cauțiuni rulat pe telefon, în browser (Pyodide).

Rulează pe telefon același cod ca Unelte → 🧮 Taxe și cauțiuni și ca Mercurius cu calculatorul (taxa_timbru,
companion_taxe), cu textele legii din pachetul `texte.json` făcut pe calculator de mercurius_offline: OUG 80/2013 și
Codul de procedură civilă (doar articolele de care are nevoie calculatorul), în forma curentă și în formele din
istoricul consolidărilor pe care calculatorul le avea descărcate.

Pagina (companion_pagina, în modul OFFLINE) cheamă `porneste(texte)` o dată, apoi `cere(...)` în loc de rețea.
"""

from __future__ import annotations

import datetime
import json
import re

import arhiva_dosare as ad
import legislatie_portal as portal
import taxa_timbru as tt
import trimitere_instanta as ti
from companion import EroareCompanion
from companion_taxe import CalculatorTaxe
from numar_dosar import normalize_case_number

_RE_NUMAR = re.compile(r"^\d+/\d+/\d{4}")

VERSIUNE_PACHET = 1
FARA_COD = -1                       # pachet fără Codul de procedură civilă: doar cauțiunile refuză calculul


class PachetTexte:
    """Formele actelor din `texte.json`, după id: {"versiune", "generat_la", "oug", "cpc", "acte": {id: act}}."""

    def __init__(self, date: dict):
        if not isinstance(date, dict) or date.get("versiune") != VERSIUNE_PACHET:
            raise ValueError("Pachetul de texte e de altă versiune decât pagina; refă Mercurius fără calculator.")
        self.generat_la = str(date.get("generat_la", ""))
        self.id_oug = int(date["oug"])
        self.id_cod = int(date.get("cpc") or FARA_COD)
        self.acte = {int(k): portal.ActLegislativ.from_dict(v) for k, v in (date.get("acte") or {}).items()}

    def forma_la_data(self, id_act: int, zi: datetime.date) -> portal.ActLegislativ | None:
        """Ca legislatie_portal.obtine_forma_la_data, dar numai din pachet (fără rețea)."""
        act = self.acte.get(int(id_act))
        if act is None:
            raise portal.EroarePortal("actul nu e în pachetul de texte de pe telefon")
        if not act.istoric:
            return act
        forma = portal.alege_consolidarea(act, zi)
        if forma is None:
            return None
        if forma.afisata or forma.id in (None, act.id):
            return act
        gasita = self.acte.get(int(forma.id))
        if gasita is None:
            raise portal.EroarePortal(
                f"forma consolidată din {portal._data_ro(forma.data)} nu e în pachetul de pe telefon (pe calculator, "
                f"în Taxe și cauțiuni, alege o dată din perioada ei, apoi refă pachetul)")
        return gasita

    def incarca(self, zi: datetime.date) -> tt.TexteLegale:
        return tt.incarca_textele(zi, forma_la_data=self.forma_la_data, id_oug=self.id_oug, id_cod=self.id_cod)


_calculator: CalculatorTaxe | None = None


def porneste(texte_json: str) -> str:
    """Citește pachetul de texte; întoarce {"generat_la": …} (JSON)."""
    global _calculator
    pachet = PachetTexte(json.loads(texte_json))
    _calculator = CalculatorTaxe(pachet.incarca)
    return json.dumps({"generat_la": pachet.generat_la})


def cere(metoda: str, ruta: str, q_json: str = "{}", corp_json: str = "{}") -> str:
    """O cerere a paginii (taxe/cazuri, taxe/caz, taxe/calcul, taxe/nota), ca prin serverul de pe calculator:
    {"ok": răspunsul} sau {"eroare": mesaj, "cod": cod}."""
    if _calculator is None:
        return json.dumps({"eroare": "Calculatorul nu e pornit.", "cod": 503})
    try:
        q = json.loads(q_json or "{}")
        corp = json.loads(corp_json or "{}")
        if not isinstance(q, dict) or not isinstance(corp, dict):
            raise EroareCompanion("Cerere invalidă.")
        return json.dumps({"ok": _calculator.raspunde(metoda, ruta, q, corp)}, ensure_ascii=False)
    except EroareCompanion as e:
        return json.dumps({"eroare": e.mesaj, "cod": e.cod}, ensure_ascii=False)
    except ValueError:
        return json.dumps({"eroare": "Cerere invalidă.", "cod": 400}, ensure_ascii=False)


# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
# Arhiva ZIP din OneDrive: aceleași reguli ca Trimite → Arhivă ZIP pe calculator (trimitere_instanta, arhiva_dosare);
# pagina citește folderele din OneDrive și face arhiva, Python-ul spune ce intră și cum se numește.
# ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────

def numar_valid(text: str) -> str:
    """Ca companion.numar_valid (fără fișa SQLite): numărul normalizat sau EroareCompanion."""
    nr = normalize_case_number(re.sub(r"\s+", "", ti.numarul_din_text(str(text or ""))))
    if not nr or not _RE_NUMAR.match(nr) or len(nr) > 60:
        raise EroareCompanion(f"„{str(text or '').strip()[:40]}” nu e un număr de dosar.")
    return nr


def _arhiva(op: str, a: dict):
    if op == "dosar":                   # numărul și numele posibile ale folderului lui (în Master / Arhiva)
        nr = numar_valid(a.get("text", ""))
        return {"nr": nr, "foldere": ad.nume_foldere_dosar(nr), "arhiva": ad.NUME_FOLDER_ARHIVA}
    if op == "grefier":                 # folderele grefier, din numele subfolderelor dosarului
        fara, cu = ti.imparte_grefier([str(x) for x in a.get("subfoldere") or []], numar_valid(a.get("nr", "")))
        return {"fara": fara, "cu": cu}
    if op == "alese":
        alegere = a.get("alegere") if a.get("alegere") in (ti.FARA, ti.CU, ti.TOATE) else None
        return ti.alege_folderele(a.get("fara") or [], a.get("cu") or [], alegere)
    if op == "radacini":                # folderul din ZIP al fiecărui folder grefier (repetate: _1, _2)
        folosite: set = set()
        return [ti.radacina_libera(str(g), folosite) for g in a.get("foldere") or []]
    if op == "fisiere":                 # care fișiere intră (fără ~$)
        return [ti.se_arhiveaza(str(n)) for n in a.get("nume") or []]
    if op == "nume":                    # numele arhivei; `acum` e ora telefonului (Pyodide merge pe UTC)
        surse = [(str(s.get("nr", "")), "", str(s.get("folder", ""))) for s in a.get("surse") or []]
        if not surse:
            raise EroareCompanion("Nu a fost arhivat niciun folder.")
        return ti.numele_arhivei(surse, datetime.datetime.fromisoformat(str(a.get("acum"))[:19]))
    raise EroareCompanion("Necunoscut.", 404)


def arhiva(op: str, args_json: str = "{}") -> str:
    """{"ok": rezultat} sau {"eroare": mesaj, "cod": cod}, ca `cere`."""
    try:
        a = json.loads(args_json or "{}")
        if not isinstance(a, dict):
            raise EroareCompanion("Cerere invalidă.")
        return json.dumps({"ok": _arhiva(op, a)}, ensure_ascii=False)
    except EroareCompanion as e:
        return json.dumps({"eroare": e.mesaj, "cod": e.cod}, ensure_ascii=False)
    except (ValueError, TypeError, AttributeError):
        return json.dumps({"eroare": "Cerere invalidă.", "cod": 400}, ensure_ascii=False)

fisiere.arhiva_dosare.py:
"""
Arhivarea dosarelor din Master: folderul dosarului se mută din Master în folderul „Arhiva” de lângă el
(<Master>\\..\\Arhiva) și, la nevoie, înapoi.

Fără Qt: dialogurile sunt în logic_list_arhiva (meniul listei, adăugarea dosarelor) și arhiva_dosare_dialog
(unealta de arhivare în masă).

Un dosar e „de arhivat” dacă:
- are starea „InFolderInstanta” (stare customizabilă din config: culoarea ei = statusul din fișa SQLite), sau
- folderul lui are cel puțin o Hotărâre: Hotarare_<nr>.docx / Hotararea_<nr>_IEM.docx (cu sau fără sufix).

Mutarea se face cu os.rename (Master și Arhiva sunt pe același disc): fie se mută tot folderul, fie nimic —
un fișier deschis în Word oprește mutarea, fără copii pe jumătate.
"""

from __future__ import annotations

import os
import re
import unicodedata
from dataclasses import dataclass, field
from typing import Iterable, List, Optional

from logger import get_logger

log = get_logger(__name__)

NUME_FOLDER_ARHIVA = "Arhiva"
ETICHETA_TRIMIS = "InFolderInstanta"
# Numele stării custom, comparat fără spații, diacritice și majuscule
_NUME_STARE_TRIMIS = ("infolderinstanta", "trimislafolderinstanta", "trimisinfolderinstanta")

# Folderele din Master care sunt dosare: 100-284-2026, 100-284-2026-R, 5331-284-2026-a1 ...
_RE_FOLDER_DOSAR = re.compile(r"^\d+-\d+-\d{4}(?:[-_].+)?$")
_EXTENSII_HOTARARE = (".docx", ".doc", ".pdf", ".rtf", ".odt")


# ---------------------------------------------------------------------------
# Numele dosarului ↔ numele folderului
# ---------------------------------------------------------------------------

def numar_curat(text: str) -> str:
    """Numărul dosarului fără marcajele listei: „[IEM] 100/284/2026 (x) ✅” → „100/284/2026”."""
    t = str(text or "").split("(")[0]
    for marcaj in ("✅", "✨", "[IEM]", "[M]"):
        t = t.replace(marcaj, "")
    t = t.strip()
    return t.split("]")[-1].strip() if "]" in t else t


def _este_recurs(nr: str) -> bool:
    return nr.endswith("*") or nr.upper().endswith("/R")


def nume_foldere_dosar(text: str) -> List[str]:
    """Numele posibile ale folderului dosarului (fără variante care ar fi ale altui dosar: la recurs nu se
    caută și folderul fără -R)."""
    nr = numar_curat(text)
    if not nr:
        return []
    if _este_recurs(nr):
        baza = nr[:-1] if nr.endswith("*") else nr[:-2]
        baza = baza.rstrip("/").replace("/", "-").replace("\\", "-")
        return [f"{baza}-R", f"{baza}_R"]
    return [nr.replace("/", "-").replace("\\", "-")]


def numar_din_folder(nume: str) -> str:
    """Numele folderului → numărul dosarului: 100-284-2026 → 100/284/2026, 100-284-2026-R → 100/284/2026*."""
    m = re.match(r"^(.*)[-_][Rr]$", nume)
    if m:
        return m.group(1).replace("-", "/") + "*"
    return nume.replace("-", "/")


def este_folder_de_dosar(nume: str) -> bool:
    return bool(_RE_FOLDER_DOSAR.match(nume or ""))


def folder_arhiva(master: str) -> str:
    """<Master>\\..\\Arhiva."""
    master = os.path.normpath(master)
    return os.path.join(os.path.dirname(master), NUME_FOLDER_ARHIVA)


def gaseste_folderul(parinte: str, text: str) -> Optional[str]:
    """Calea folderului dosarului direct în `parinte` (nume comparat fără majuscule); None dacă lipsește."""
    if not parinte or not os.path.isdir(parinte):
        return None
    candidati = [c.lower() for c in nume_foldere_dosar(text)]
    if not candidati:
        return None
    try:
        nume = {e.name.lower(): e.name for e in os.scandir(parinte) if e.is_dir()}
    except OSError:
        log.warning("Folderul %s nu poate fi listat", parinte, exc_info=True)
        return None
    for c in candidati:
        if c in nume:
            return os.path.join(parinte, nume[c])
    return None


# ---------------------------------------------------------------------------
# Criteriile: Hotărârea din folder, starea „InFolderInstanta”
# ---------------------------------------------------------------------------

def _fara_diacritice(s: str) -> str:
    return "".join(c for c in unicodedata.normalize("NFD", s) if unicodedata.category(c) != "Mn")


def hotararile_din_folder(folder: str, nume_folder: Optional[str] = None) -> List[str]:
    """Hotărârile dosarului din folder (doar primul nivel): Hotarare_<nr>[sufix].ext / Hotararea_<nr>[sufix].ext,
    unde <nr> e numele folderului (100-284-2026, 100-284-2026-R). Copiile temporare Word (~$) nu contează."""
    nume_folder = nume_folder or os.path.basename(os.path.normpath(folder))
    nr = re.escape(_fara_diacritice(nume_folder).lower())
    tipar = re.compile(rf"^hotararea?[ _-]+{nr}(?:[ _\-.(].*)?$")
    try:
        fisiere = [e.name for e in os.scandir(folder) if e.is_file()]
    except OSError:
        log.warning("Folderul %s nu poate fi listat", folder, exc_info=True)
        return []
    gasite = []
    for f in sorted(fisiere):
        if f.startswith("~$"):
            continue
        baza, ext = os.path.splitext(f)
        if ext.lower() in _EXTENSII_HOTARARE and tipar.match(_fara_diacritice(baza).lower()):
            gasite.append(f)
    return gasite


def _nume_comparabil(eticheta: str) -> str:
    return re.sub(r"[^a-z0-9]", "", _fara_diacritice(eticheta or "").lower())


def culoarea_statusului_trimis(stari=None) -> Optional[str]:
    """Culoarea (hex, litere mici) stării custom „InFolderInstanta”; None dacă starea nu e definită."""
    if stari is None:
        try:
            from states_config import load_persistent_custom_states
            stari = load_persistent_custom_states()
        except Exception:
            log.warning("Stările customizabile nu pot fi citite", exc_info=True)
            return None
    for hex_color, eticheta in stari or []:
        if _nume_comparabil(eticheta) in _NUME_STARE_TRIMIS:
            return (hex_color or "").strip().lower() or None
    return None


def are_statusul_trimis(text: str, culoare_status: Optional[str], culoare_rand: Optional[str] = None,
                        db=None) -> bool:
    """Dosarul are starea „InFolderInstanta”: culoarea rândului din listă (dacă e dată), altfel statusul din fișă."""
    if not culoare_status:
        return False
    culoare = (culoare_rand or "").strip().lower()
    if not culoare:
        try:
            if db is None:
                from fisa_db import get_db
                db = get_db()
            culoare = ((db.get_fisa(numar_curat(text)) or {}).get("status") or "").strip().lower()
        except Exception:
            log.warning("Fișa dosarului %s nu poate fi citită", text, exc_info=True)
            return False
    return culoare == culoare_status.lower()


# ---------------------------------------------------------------------------
# Mutarea
# ---------------------------------------------------------------------------

def _muta(sursa: str, parinte_destinatie: str) -> str:
    os.makedirs(parinte_destinatie, exist_ok=True)
    destinatie = os.path.join(parinte_destinatie, os.path.basename(os.path.normpath(sursa)))
    if os.path.exists(destinatie):
        raise FileExistsError(f"există deja {destinatie}")
    os.rename(sursa, destinatie)
    return destinatie


def _jurnal_fisa(text: str, actiune: str, sursa: str, destinatie: str):
    try:
        from fisa_db import get_db
        get_db().log_modification(numar_curat(text), actiune, {"din": sursa, "in": destinatie},
                                  text_override=f"{actiune}: {sursa} → {destinatie}")
    except Exception:
        log.debug("Mutarea nu a putut fi trecută în istoricul fișei %s", text, exc_info=True)


def arhiveaza(master: str, text: str) -> str:
    """Mută folderul dosarului din Master în Arhivă; întoarce noua cale. FileNotFoundError dacă nu e în Master."""
    sursa = gaseste_folderul(master, text)
    if not sursa:
        raise FileNotFoundError(f"folderul dosarului nu este în Master ({master})")
    destinatie = _muta(sursa, folder_arhiva(master))
    log.info("Dosar arhivat: %s -> %s", sursa, destinatie)
    _jurnal_fisa(text, "Arhivat", sursa, destinatie)
    return destinatie


def dezarhiveaza(master: str, text: str) -> str:
    """Mută folderul dosarului din Arhivă înapoi în Master; întoarce noua cale."""
    sursa = gaseste_folderul(folder_arhiva(master), text)
    if not sursa:
        raise FileNotFoundError("folderul dosarului nu este în Arhivă")
    destinatie = _muta(sursa, master)
    log.info("Dosar scos din arhivă: %s -> %s", sursa, destinatie)
    _jurnal_fisa(text, "Scos din arhivă", sursa, destinatie)
    return destinatie


def dosarele_arhivate(master: str, texte: Iterable[str]) -> List[str]:
    """Dintre dosarele date, cele al căror folder e în Arhivă și nu e (și) în Master."""
    if not master or not os.path.isdir(master):
        return []
    arhiva = folder_arhiva(master)
    if not os.path.isdir(arhiva):
        return []
    rez = []
    for t in texte:
        if t and t not in rez and gaseste_folderul(arhiva, t) and not gaseste_folderul(master, t):
            rez.append(t)
    return rez


# ---------------------------------------------------------------------------
# Unealta de arhivare în masă: dosarele din Master care se pot arhiva
# ---------------------------------------------------------------------------

@dataclass
class CandidatArhivare:
    numar: str
    folder: str
    are_status: bool = False
    hotarari: List[str] = field(default_factory=list)

    @property
    def motiv(self) -> str:
        parti = []
        if self.are_status:
            parti.append(f"Status {ETICHETA_TRIMIS}")
        if self.hotarari:
            parti.append("Hotărâre: " + ", ".join(self.hotarari))
        return "; ".join(parti)


def cauta_de_arhivat(master: str, db=None, culoare_status: Optional[str] = "") -> List[CandidatArhivare]:
    """Folderele de dosar din Master care au starea „InFolderInstanta” sau cel puțin o Hotărâre.
    culoare_status: culoarea stării ("" = citită din config; None = starea nu există)."""
    if not master or not os.path.isdir(master):
        return []
    if culoare_status == "":
        culoare_status = culoarea_statusului_trimis()
    if db is None and culoare_status:
        try:
            from fisa_db import get_db
            db = get_db()
        except Exception:
            log.warning("Baza fișelor nu e disponibilă: arhivarea se face doar după Hotărâri", exc_info=True)
            culoare_status = None
    rez = []
    try:
        intrari = sorted((e for e in os.scandir(master) if e.is_dir() and este_folder_de_dosar(e.name)),
                         key=lambda e: e.name.lower())
    except OSError:
        log.warning("Masterul %s nu poate fi listat", master, exc_info=True)
        return []
    for e in intrari:
        numar = numar_din_folder(e.name)
        are_status = are_statusul_trimis(numar, culoare_status, db=db) if culoare_status else False
        hotarari = hotararile_din_folder(e.path, e.name)
        if are_status or hotarari:
            rez.append(CandidatArhivare(numar, e.path, are_status, hotarari))
    return rez

fisiere.trimitere_instanta.py:
"""
Trimite → Folder / Arhivă ZIP: folderele generate pentru instanță de „Trimite la grefier” și arhiva lor.

Aceeași logică pentru meniul listei (logic_list_trimitere, cu întrebările în dialoguri Qt) și pentru telefon
(companion, cu întrebările pe telefon). Fără Qt.
"""

from __future__ import annotations

import datetime
import os
import zipfile
from typing import Iterable, List, Optional, Sequence, Tuple

FARA, CU, TOATE = "fara", "cu", "toate"

# (numărul dosarului, calea folderului grefier, numele folderului)
SursaArhiva = Tuple[str, str, str]


def grefier_folder_base(clean_nr: str) -> str:
    """Numele folderului dosarului (și al folderului grefier fără sufix): 100/284/2026 → 100-284-2026."""
    return clean_nr.replace("/", "-").replace("*", "-R")


def numarul_din_text(text: str) -> str:
    """Numărul curat din textul unui rând din listă („✅ [3] 100/284/2026 (C3)” → 100/284/2026)."""
    text = (text or "").split("(")[0].replace("✅", "").strip()
    return text.split("]")[-1].strip() if "]" in text else text


def foldere_grefier(case_folder: str, clean_nr: str) -> Tuple[List[str], List[str]]:
    """Folderele generate de „Trimite la grefier” în folderul dosarului: (fără sufix, cu sufix), alfabetic.
    Ridică OSError dacă folderul nu poate fi citit."""
    return imparte_grefier([d for d in os.listdir(case_folder) if os.path.isdir(os.path.join(case_folder, d))],
                           clean_nr)


def imparte_grefier(subfoldere: Iterable[str], clean_nr: str) -> Tuple[List[str], List[str]]:
    """Dintre numele subfolderelor dosarului, folderele grefier: (fără sufix, cu sufix), alfabetic. Folosit și pe
    telefon (Mercurius fără calculator), cu numele citite din OneDrive."""
    baza = grefier_folder_base(clean_nr)
    gasite = [d for d in subfoldere if d.startswith(baza)]
    return sorted(d for d in gasite if d == baza), sorted(d for d in gasite if d != baza)


def alege_folderele(fara_sufix: Sequence[str], cu_sufix: Sequence[str], alegere: Optional[str]) -> List[str]:
    """Folderele de trimis după alegerea judecătorului (fără sufix / cu sufix / toate); fără alegere = toate."""
    if alegere == FARA:
        return list(fara_sufix)
    if alegere == CU:
        return list(cu_sufix)
    return list(fara_sufix) + list(cu_sufix)


def scrie_arhiva(surse: Iterable[SursaArhiva], zip_path: str) -> Tuple[int, List[str]]:
    """Pune folderele grefier în arhivă (fiecare = un folder în ZIP; nume repetate → _1, _2), fără fișierele
    temporare Word (~$). Returnează (câte foldere au intrat, erori). Ridică excepția dacă arhiva nu se poate crea."""
    arhivate, erori = 0, []
    with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as zf:
        folosite = set()
        for clean_nr, src_path, g_folder in surse:
            radacina = radacina_libera(g_folder, folosite)
            try:
                for root, _dirs, files in os.walk(src_path):
                    for f in files:
                        if not se_arhiveaza(f):
                            continue
                        full = os.path.join(root, f)
                        zf.write(full, os.path.join(radacina, os.path.relpath(full, src_path)))
                arhivate += 1
            except Exception as e:
                erori.append(f"{clean_nr}: Eroare arhivare {g_folder} ({e})")
    return arhivate, erori


def radacina_libera(g_folder: str, folosite: set) -> str:
    """Folderul din ZIP pentru folderul grefier: numele lui sau, dacă e deja în arhivă, _1, _2 (fără majuscule)."""
    radacina = g_folder
    contor = 1
    while radacina.lower() in folosite:
        radacina = f"{g_folder}_{contor}"
        contor += 1
    folosite.add(radacina.lower())
    return radacina


def se_arhiveaza(nume_fisier: str) -> bool:
    """Fișierele temporare Word (~$…) nu intră în arhivă."""
    return not nume_fisier.startswith("~$")


def numele_arhivei(surse: Sequence[SursaArhiva], acum: Optional[datetime.datetime] = None) -> str:
    """Numele propus: folderul grefier (unul singur), dosarul (mai multe foldere ale aceluiași dosar) sau
    Dosare_instanta_<data>.zip."""
    if len(surse) == 1:
        return f"{surse[0][2]}.zip"
    if len({nr for nr, _, _ in surse}) == 1:
        return f"{grefier_folder_base(surse[0][0])}.zip"
    acum = acum or datetime.datetime.now()
    return f"Dosare_instanta_{acum.strftime('%Y-%m-%d_%H-%M')}.zip"


def cale_libera(cale: str) -> str:
    """Calea dată sau, dacă există deja, aceeași cu _1, _2... înaintea extensiei (nu se suprascrie nimic)."""
    if not os.path.exists(cale):
        return cale
    baza, ext = os.path.splitext(cale)
    contor = 1
    while os.path.exists(f"{baza}_{contor}{ext}"):
        contor += 1
    return f"{baza}_{contor}{ext}"

